    [Fact]
    public async Task ResolveBoundaryLoopCageControl_SelectsHoleLoopForInnerBoundaryVertices()
    {
        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(workingDirectory);
        var inputFile = Path.Combine(workingDirectory, "dense_window_loop_controls_0.nif");

        var vertices = new List<(float X, float Y, float Z)>();
        var triangles = new List<(ushort A, ushort B, ushort C)>();
        const int ringCount = 5;
        const int segments = 12;
        for (var ringIndex = 0; ringIndex < ringCount; ringIndex++)
        {
            var radius = 1.35f - (ringIndex * 0.22f);
            for (var segment = 0; segment < segments; segment++)
            {
                var angle = (MathF.PI * 2f * segment) / segments;
                vertices.Add((MathF.Cos(angle) * radius, MathF.Sin(angle) * radius, 0.55f + (ringIndex * 0.015f)));
            }
        }

        for (ushort ringIndex = 0; ringIndex < ringCount - 1; ringIndex++)
        {
            for (ushort segment = 0; segment < segments; segment++)
            {
                var nextSegment = (ushort)((segment + 1) % segments);
                var a = (ushort)((ringIndex * segments) + segment);
                var b = (ushort)((ringIndex * segments) + nextSegment);
                var c = (ushort)(((ringIndex + 1) * segments) + segment);
                var d = (ushort)(((ringIndex + 1) * segments) + nextSegment);
                triangles.Add((a, c, b));
                triangles.Add((b, c, d));
            }
        }

        await SyntheticNifTestData.WriteBsTriShapeStyleAsync(inputFile, vertices, triangles);

        try
        {
            var buildCageMethod = typeof(LocalExportService).GetMethod("BuildExportDeformationCage", BindingFlags.NonPublic | BindingFlags.Static);
            var buildTopologyMethod = typeof(LocalExportService).GetMethod("BuildTopologyTransformContext", BindingFlags.NonPublic | BindingFlags.Static);
            var resolveIslandMethod = typeof(LocalExportService).GetMethod("ResolveIslandCageControl", BindingFlags.NonPublic | BindingFlags.Static);
            var resolveLoopMethod = typeof(LocalExportService).GetMethod("ResolveBoundaryLoopCageControl", BindingFlags.NonPublic | BindingFlags.Static);
            Assert.NotNull(buildCageMethod);
            Assert.NotNull(buildTopologyMethod);
            Assert.NotNull(resolveIslandMethod);
            Assert.NotNull(resolveLoopMethod);

            var cage = new DeformationCage(
                "test-cage",
                new Dictionary<string, CageRegion>(StringComparer.OrdinalIgnoreCase)
                {
                    ["chest"] = new(0.72f, 0.26f, 0.50f, 0.96f, 0.50f, 0.96f, 0.72f, 0.18f, 0.08f, 0.02f),
                    ["waist"] = new(0.56f, 0.22f, 0.50f, 0.90f, 0.50f, 0.90f, 0.62f, 0.16f, 0.06f, 0.00f)
                });

            var result = Assert.IsType<DeformationCage>(buildCageMethod!.Invoke(null, [new[] { inputFile }, cage]));
            var topologySummary = NifGeometrySignatureReader.TryReadTopologySummary(inputFile);
            Assert.NotNull(topologySummary);
            var topologyContext = buildTopologyMethod!.Invoke(null,
            [
                vertices.Select(static vertex => (vertex.X, vertex.Y, vertex.Z)).ToArray(),
                topologySummary
            ]);
            Assert.NotNull(topologyContext);

            var islandControl = resolveIslandMethod!.Invoke(null, [result, inputFile, topologyContext, 48]);
            Assert.NotNull(islandControl);

            var loopControl = resolveLoopMethod!.Invoke(null, [islandControl, topologyContext, 48]);
            Assert.NotNull(loopControl);
            Assert.True((bool)(loopControl!.GetType().GetProperty("IsHole")!.GetValue(loopControl) ?? false));
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }

    [Fact]
    public void BuildTransferIslandEdgeNetworks_EstimatesReusableNetworksWithoutExplicitTopology()
    {
        var method = typeof(LocalExportService).GetMethod("BuildTransferIslandEdgeNetworks", BindingFlags.NonPublic | BindingFlags.Static);
        Assert.NotNull(method);

        var normalizedVertices = new[]
        {
            new MeshVertex(0.10f, 0.50f, 0.10f),
            new MeshVertex(0.14f, 0.52f, 0.12f),
            new MeshVertex(0.18f, 0.48f, 0.14f),
            new MeshVertex(0.80f, 0.50f, 0.78f),
            new MeshVertex(0.84f, 0.52f, 0.80f),
            new MeshVertex(0.88f, 0.48f, 0.82f)
        };
        var transferIslands = new[] { 0, 0, 0, 1, 1, 1 };
        var boundaryFlags = new[] { true, false, true, true, false, true };

        var result = method!.Invoke(null, [normalizedVertices, transferIslands, boundaryFlags, null]);
        var networks = Assert.IsAssignableFrom<System.Collections.IDictionary>(result);

        Assert.Equal(2, networks.Count);
        foreach (System.Collections.DictionaryEntry entry in networks)
        {
            var network = entry.Value!;
            var vertexIndexes = Assert.IsAssignableFrom<System.Collections.IEnumerable>(network.GetType().GetProperty("VertexIndexes")!.GetValue(network));
            var adjacency = Assert.IsAssignableFrom<System.Collections.IDictionary>(network.GetType().GetProperty("AdjacencyByVertex")!.GetValue(network));
            var interiorEdges = Assert.IsAssignableFrom<System.Collections.IEnumerable>(network.GetType().GetProperty("InteriorEdges")!.GetValue(network));
            Assert.Equal(3, vertexIndexes.Cast<object>().Count());
            Assert.True(adjacency.Count > 0);
            Assert.True(interiorEdges.Cast<object>().Any());
            Assert.False((bool)(network.GetType().GetProperty("UsesExplicitTopology")!.GetValue(network) ?? true));
        }
    }

    [Fact]
    public void BuildMorphTransferIslandMatches_PrefersSimilarEstimatedEdgeNetworks()
    {
        var method = typeof(LocalExportService).GetMethod("BuildMorphTransferIslandMatches", BindingFlags.NonPublic | BindingFlags.Static);
        var networkType = typeof(TransferIslandEdgeNetwork);
        Assert.NotNull(method);
        Assert.NotNull(networkType);

        object CreateNetwork(
            int islandId,
            IReadOnlyList<int> vertexIndexes,
            IReadOnlyList<int> boundaryVertexIndexes,
            IReadOnlyList<(int, int)> boundaryEdges,
            IReadOnlyList<(int, int)> interiorEdges,
            IReadOnlyDictionary<int, IReadOnlyList<int>> adjacency,
            int nonManifoldEdgeCount,
            float manifoldScore,
            bool usesExplicitTopology)
        {
            var ctor = networkType!.GetConstructors(BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)
                .Single(candidate => candidate.GetParameters().Length == 9);
            return ctor.Invoke([islandId, vertexIndexes, boundaryVertexIndexes, boundaryEdges, interiorEdges, adjacency, nonManifoldEdgeCount, manifoldScore, usesExplicitTopology]);
        }

        var sourceVertices = new[]
        {
            new MeshVertex(0.25f, 0.50f, 0.50f),
            new MeshVertex(0.35f, 0.50f, 0.50f),
            new MeshVertex(0.10f, 0.50f, 0.50f),
            new MeshVertex(0.50f, 0.50f, 0.50f)
        };
        var targetVertices = new[]
        {
            new MeshVertex(0.20f, 0.50f, 0.50f),
            new MeshVertex(0.40f, 0.50f, 0.50f)
        };
        var sourceIslands = new[] { 0, 0, 1, 1 };
        var targetIslands = new[] { 0, 0 };

        var sourceNetworkDictionaryType = typeof(Dictionary<,>).MakeGenericType(typeof(int), networkType!);
        var targetNetworkDictionaryType = typeof(Dictionary<,>).MakeGenericType(typeof(int), networkType!);
        var sourceNetworks = (System.Collections.IDictionary)Activator.CreateInstance(sourceNetworkDictionaryType)!;
        var targetNetworks = (System.Collections.IDictionary)Activator.CreateInstance(targetNetworkDictionaryType)!;

        sourceNetworks[0] = CreateNetwork(
            0,
            new[] { 0, 1 },
            new[] { 0, 1 },
            new[] { (0, 1) },
            Array.Empty<(int, int)>(),
            new Dictionary<int, IReadOnlyList<int>> { [0] = [1], [1] = [0] },
            0,
            1f,
            false);
        sourceNetworks[1] = CreateNetwork(
            1,
            new[] { 2, 3 },
            new[] { 2, 3 },
            new[] { (2, 3) },
            new[] { (2, 3) },
            new Dictionary<int, IReadOnlyList<int>> { [2] = [3], [3] = [2] },
            2,
            0.35f,
            false);
        targetNetworks[0] = CreateNetwork(
            0,
            new[] { 0, 1 },
            new[] { 0, 1 },
            new[] { (0, 1) },
            Array.Empty<(int, int)>(),
            new Dictionary<int, IReadOnlyList<int>> { [0] = [1], [1] = [0] },
            0,
            1f,
            false);

        var result = Assert.IsType<int[]>(method!.Invoke(null, [sourceVertices, targetVertices, sourceIslands, targetIslands, sourceNetworks, targetNetworks]));

        Assert.Single(result);
        Assert.Equal(0, result[0]);
    }

    [Fact]
    public void BuildMorphTransferIslandTransferSummaries_AggregatesBoundaryAndAdjacencyMetadata()
    {
        var profilesMethod = typeof(LocalExportService).GetMethod("BuildMorphTransferIslandProfiles", BindingFlags.NonPublic | BindingFlags.Static);
        var summariesMethod = typeof(LocalExportService).GetMethod("BuildMorphTransferIslandTransferSummaries", BindingFlags.NonPublic | BindingFlags.Static);
        Assert.NotNull(profilesMethod);
        Assert.NotNull(summariesMethod);

        var sourceVertices = new[]
        {
            new MeshVertex(0.10f, 0.50f, 0.10f),
            new MeshVertex(0.14f, 0.52f, 0.12f),
            new MeshVertex(0.18f, 0.48f, 0.14f),
            new MeshVertex(0.58f, 0.50f, 0.10f),
            new MeshVertex(0.62f, 0.52f, 0.12f),
            new MeshVertex(0.66f, 0.48f, 0.14f)
        };
        var targetVertices = new[]
        {
            new MeshVertex(0.12f, 0.50f, 0.10f),
            new MeshVertex(0.16f, 0.52f, 0.12f),
            new MeshVertex(0.20f, 0.48f, 0.14f),
            new MeshVertex(0.34f, 0.50f, 0.11f),
            new MeshVertex(0.38f, 0.52f, 0.13f),
            new MeshVertex(0.42f, 0.48f, 0.15f)
        };

        var sourceIslands = new[] { 0, 0, 0, 1, 1, 1 };
        var targetIslands = new[] { 0, 0, 0, 1, 1, 1 };
        var sourceZones = Enumerable.Repeat(17, sourceVertices.Length).ToArray();
        var targetZones = Enumerable.Repeat(17, targetVertices.Length).ToArray();
        var sourceBoundaryFlags = new[] { true, false, true, true, false, true };
        var targetBoundaryFlags = new[] { true, false, true, true, false, true };

        var sourceProfiles = Assert.IsAssignableFrom<System.Collections.IDictionary>(
            profilesMethod!.Invoke(null, [sourceVertices, sourceZones, sourceIslands, sourceBoundaryFlags, null, false]));
        var targetProfiles = Assert.IsAssignableFrom<System.Collections.IDictionary>(
            profilesMethod.Invoke(null, [targetVertices, targetZones, targetIslands, targetBoundaryFlags, null, false]));

        var summaries = Assert.IsAssignableFrom<System.Collections.IDictionary>(
            summariesMethod!.Invoke(null, [sourceVertices, targetVertices, sourceIslands, targetIslands, null, null, sourceProfiles, targetProfiles]));

        Assert.Equal(2, summaries.Count);
        var firstSummary = summaries[0]!;
        var preferredSourceIsland = (int)(firstSummary.GetType().GetProperty("PreferredSourceIslandId")?.GetValue(firstSummary) ?? -1);
        var boundaryBlendBias = (float)(firstSummary.GetType().GetProperty("BoundaryBlendBias")?.GetValue(firstSummary) ?? 0f);
        var adjacentTargetIslands = Assert.IsAssignableFrom<System.Collections.IEnumerable>(
            firstSummary.GetType().GetProperty("AdjacentTargetIslands")!.GetValue(firstSummary));
        var sourceInfluences = Assert.IsAssignableFrom<System.Collections.IEnumerable>(
            firstSummary.GetType().GetProperty("SourceInfluences")!.GetValue(firstSummary));

        Assert.Equal(0, preferredSourceIsland);
        Assert.True(boundaryBlendBias > 0f);
        Assert.True(adjacentTargetIslands.Cast<object>().Any());
        Assert.True(sourceInfluences.Cast<object>().Count() >= 2);
    }

    [Fact]
    public async Task BuildTopologyTransformContext_GivesInnerBoundaryLoopsStrongerPreservationWeight()
    {
        var dir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        var meshPath = Path.Combine(dir, "openwork_boundary_weights_0.nif");
        var vertices = new (float X, float Y, float Z)[]
        {
            ( 1.20f,  0.00f, 0.40f), ( 0.60f,  1.04f, 0.40f), (-0.60f,  1.04f, 0.40f),
            (-1.20f,  0.00f, 0.40f), (-0.60f, -1.04f, 0.40f), ( 0.60f, -1.04f, 0.40f),
            ( 0.45f,  0.00f, 0.40f), ( 0.225f,  0.39f, 0.40f), (-0.225f,  0.39f, 0.40f),
            (-0.45f,  0.00f, 0.40f), (-0.225f, -0.39f, 0.40f), ( 0.225f, -0.39f, 0.40f)
        };
        var triangles = new (ushort A, ushort B, ushort C)[]
        {
            (0, 1, 7), (0, 7, 6),
            (1, 2, 8), (1, 8, 7),
            (2, 3, 9), (2, 9, 8),
            (3, 4,10), (3,10, 9),
            (4, 5,11), (4,11,10),
            (5, 0, 6), (5, 6,11)
        };
        await SyntheticNifTestData.WriteBsTriShapeStyleAsync(meshPath, vertices, triangles);

        try
        {
            var topologySummary = NifGeometrySignatureReader.TryReadTopologySummary(meshPath);
            Assert.NotNull(topologySummary);

            var buildContextMethod = typeof(LocalExportService).GetMethod("BuildTopologyTransformContext", BindingFlags.NonPublic | BindingFlags.Static);
            Assert.NotNull(buildContextMethod);

            var context = buildContextMethod!.Invoke(null,
            [
                vertices.Select(static vertex => (vertex.X, vertex.Y, vertex.Z)).ToArray(),
                topologySummary
            ]);
            Assert.NotNull(context);

            var weights = Assert.IsType<float[]>(context!.GetType().GetProperty("BoundaryVertexWeights", BindingFlags.Public | BindingFlags.Instance)!.GetValue(context));
            Assert.Equal(vertices.Length, weights.Length);
            Assert.True(weights[6] > weights[0], $"Expected inner authored loop vertices to receive stronger preservation weighting than the outer perimeter, got outer={weights[0]} inner={weights[6]}.");
            Assert.True(weights[6] >= 0.12f, $"Expected authored inner loop weighting to be material, got {weights[6]}.");
        }
        finally
        {
            Directory.Delete(dir, recursive: true);
        }
    }

