    [Fact]
    public async Task BuildTopologyTransformContext_GivesNonManifoldIslandsStrongerBoundaryPreservationBias()
    {
        var dir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        var nonManifoldPath = Path.Combine(dir, "nonmanifold_transform_weights_0.nif");
        var manifoldPath = Path.Combine(dir, "manifold_transform_weights_0.nif");
        var vertices = new (float X, float Y, float Z)[]
        {
            (-0.60f,  0.00f, 0.50f),
            ( 0.60f,  0.00f, 0.50f),
            ( 0.00f,  0.60f, 0.50f),
            ( 0.00f, -0.60f, 0.50f),
            ( 0.00f,  0.60f, 1.00f)
        };
        var triangles = new (ushort A, ushort B, ushort C)[]
        {
            (0, 1, 2),
            (1, 0, 3),
            (0, 1, 4),
            (0, 2, 4)
        };
        var manifoldTriangles = new (ushort A, ushort B, ushort C)[]
        {
            (0, 2, 1),
            (0, 3, 1),
            (0, 2, 4),
            (1, 4, 2)
        };
        await SyntheticNifTestData.WriteBsTriShapeStyleAsync(nonManifoldPath, vertices, triangles);
        await SyntheticNifTestData.WriteBsTriShapeStyleAsync(manifoldPath, vertices, manifoldTriangles);

        try
        {
            var nonManifoldSummary = NifGeometrySignatureReader.TryReadTopologySummary(nonManifoldPath);
            var manifoldSummary = NifGeometrySignatureReader.TryReadTopologySummary(manifoldPath);
            Assert.NotNull(nonManifoldSummary);
            Assert.NotNull(manifoldSummary);

            var buildContextMethod = typeof(LocalExportService).GetMethod("BuildTopologyTransformContext", BindingFlags.NonPublic | BindingFlags.Static);
            Assert.NotNull(buildContextMethod);

            var nonManifoldContext = buildContextMethod!.Invoke(null,
            [
                vertices.Select(static vertex => (vertex.X, vertex.Y, vertex.Z)).ToArray(),
                nonManifoldSummary
            ]);
            var manifoldContext = buildContextMethod.Invoke(null,
            [
                vertices.Select(static vertex => (vertex.X, vertex.Y, vertex.Z)).ToArray(),
                manifoldSummary
            ]);
            Assert.NotNull(nonManifoldContext);
            Assert.NotNull(manifoldContext);

            var nonManifoldBias = Assert.IsType<float>(nonManifoldContext!.GetType().GetProperty("BoundaryPreservationWeight", BindingFlags.Public | BindingFlags.Instance)!.GetValue(nonManifoldContext));
            var manifoldBias = Assert.IsType<float>(manifoldContext!.GetType().GetProperty("BoundaryPreservationWeight", BindingFlags.Public | BindingFlags.Instance)!.GetValue(manifoldContext));
            Assert.True(nonManifoldBias > manifoldBias, $"Expected explicit non-manifold topology to raise transform-stage preservation bias above a comparable manifold mesh, got non-manifold={nonManifoldBias} manifold={manifoldBias}.");
        }
        finally
        {
            Directory.Delete(dir, recursive: true);
        }
    }

    [Fact]
    public async Task ConvertAsync_WithSyntheticNif_AppliesVertexTransform()
    {
        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var outputDirectory = Path.Combine(workingDirectory, "output");
        Directory.CreateDirectory(workingDirectory);
        var inputFile = Path.Combine(workingDirectory, "synthetic_armor.nif");
        var sourceVertices = SyntheticNifTestData.CreateUpperBodyArmorVertices();
        await SyntheticNifTestData.WriteAsync(inputFile, sourceVertices);

        try
        {
            var orchestrator = StandaloneConversionModules.CreateDefault();
            var result = await orchestrator.ConvertAsync(new ConversionRequest(inputFile, "3BA", outputDirectory));

            Assert.True(result.Success);
            var writtenPath = Path.Combine(outputDirectory, "meshes", "slidesmith", "3ba", "synthetic_armor.nif");
            Assert.True(File.Exists(writtenPath), "Converted NIF was not written.");

            var sourceBytes = await File.ReadAllBytesAsync(inputFile);
            var writtenBytes = await File.ReadAllBytesAsync(writtenPath);
            Assert.NotEmpty(writtenBytes);
            Assert.Contains("Gamebryo File Format", System.Text.Encoding.ASCII.GetString(writtenBytes), StringComparison.Ordinal);

            var sourceRead = ReadEmbeddedVertices(sourceBytes);
            var transformedRead = ReadEmbeddedVertices(writtenBytes);
            Assert.Equal(sourceRead.Count, transformedRead.Count);

            var anyVertexChanged = sourceRead.Zip(transformedRead, (src, dst) =>
                    Math.Abs(src.X - dst.X) > 0.0001f ||
                    Math.Abs(src.Y - dst.Y) > 0.0001f ||
                    Math.Abs(src.Z - dst.Z) > 0.0001f)
                .Any(changed => changed);

            Assert.True(anyVertexChanged, "Expected at least one synthetic vertex to be transformed.");
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }

    [Fact]
    public async Task AssessTopologyAndUvMismatch_FlagsRegionalDriftWarnings()
    {
        var method = typeof(LocalExportService).GetMethod("AssessTopologyAndUvMismatch", BindingFlags.NonPublic | BindingFlags.Static);
        Assert.NotNull(method);

        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(workingDirectory);
        var sourceFile = Path.Combine(workingDirectory, "extreme_drift_source.nif");
        var convertedFile = Path.Combine(workingDirectory, "extreme_drift_converted.nif");
        var sourceVertices = SyntheticNifTestData.CreateUpperBodyArmorVertices();
        var convertedVertices = sourceVertices
            .Select(vertex => (
                X: vertex.X * 1.08f,
                Y: vertex.Y * 0.94f,
                Z: vertex.Z))
            .ToArray();
        await SyntheticNifTestData.WriteAsync(sourceFile, sourceVertices);
        await SyntheticNifTestData.WriteAsync(convertedFile, convertedVertices);

        try
        {
            var regionalMorphing = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase)
            {
                ["breasts"] = 1.34d,
                ["chest"] = 1.28d,
                ["waist"] = 0.74d
            };
            var assessment = method!.Invoke(null, [new[] { sourceFile }, new[] { convertedFile }, regionalMorphing, true, false, 0])!;
            var topologyMismatchRisk = Assert.IsType<bool>(assessment.GetType().GetField("Item1")!.GetValue(assessment));
            var qualityWarnings = Assert.IsAssignableFrom<IReadOnlyList<string>>(assessment.GetType().GetField("Item5")!.GetValue(assessment));

            Assert.True(topologyMismatchRisk);
            Assert.Contains(qualityWarnings, warning => warning.StartsWith("regional-drift:", StringComparison.OrdinalIgnoreCase));
            var regionalWarning = qualityWarnings.First(warning => warning.StartsWith("regional-drift:", StringComparison.OrdinalIgnoreCase));
            Assert.Contains("breasts", regionalWarning, StringComparison.OrdinalIgnoreCase);
            Assert.Contains("chest", regionalWarning, StringComparison.OrdinalIgnoreCase);
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }

