public sealed class WeightVariantPairTests
{
    [Fact]
    public void DetectWeightVariantPairs_FullPair_DetectsBothWeights()
    {
        var meshFiles = new List<string>
        {
            "/tmp/armor/cuirass_0.nif",
            "/tmp/armor/cuirass_1.nif"
        };

        var pairs = LocalArmorImportService.DetectWeightVariantPairs(meshFiles);

        Assert.Single(pairs);
        Assert.Equal("cuirass", pairs[0].BaseName);
        Assert.NotNull(pairs[0].LowWeightMesh);
        Assert.NotNull(pairs[0].HighWeightMesh);
        Assert.EndsWith("cuirass_0.nif", pairs[0].LowWeightMesh, StringComparison.OrdinalIgnoreCase);
        Assert.EndsWith("cuirass_1.nif", pairs[0].HighWeightMesh, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void DetectWeightVariantPairs_MultiplePairs_DetectsAll()
    {
        var meshFiles = new List<string>
        {
            "/tmp/armor/cuirass_0.nif",
            "/tmp/armor/cuirass_1.nif",
            "/tmp/armor/boots_0.nif",
            "/tmp/armor/boots_1.nif",
            "/tmp/armor/gloves_0.nif",
            "/tmp/armor/gloves_1.nif"
        };

        var pairs = LocalArmorImportService.DetectWeightVariantPairs(meshFiles);

        Assert.Equal(3, pairs.Count);
        Assert.All(pairs, p => Assert.NotNull(p.LowWeightMesh));
        Assert.All(pairs, p => Assert.NotNull(p.HighWeightMesh));
    }

    [Fact]
    public void DetectWeightVariantPairs_MissingHighWeight_ReportsIncomplete()
    {
        var meshFiles = new List<string>
        {
            "/tmp/armor/gauntlets_0.nif"
        };

        var pairs = LocalArmorImportService.DetectWeightVariantPairs(meshFiles);

        Assert.Single(pairs);
        Assert.NotNull(pairs[0].LowWeightMesh);
        Assert.Null(pairs[0].HighWeightMesh);
    }

    [Fact]
    public void DetectWeightVariantPairs_NoWeightSuffix_ReturnsEmpty()
    {
        var meshFiles = new List<string>
        {
            "/tmp/armor/helmet.nif"
        };

        var pairs = LocalArmorImportService.DetectWeightVariantPairs(meshFiles);

        Assert.Empty(pairs);
    }

    [Fact]
    public async Task ConvertAsync_WithDefaultModules_WeightVariantStepPresent()
    {
        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var outputDirectory = Path.Combine(workingDirectory, "output");
        Directory.CreateDirectory(workingDirectory);

        // Provide a _0/_1 pair so the weight-variants step fires.
        var mesh0 = Path.Combine(workingDirectory, "cuirass_0.nif");
        var mesh1 = Path.Combine(workingDirectory, "cuirass_1.nif");
        await File.WriteAllTextAsync(mesh0, "mesh");
        await File.WriteAllTextAsync(mesh1, "mesh");

        try
        {
            var orchestrator = StandaloneConversionModules.CreateDefault();
            var result = await orchestrator.ConvertAsync(new ConversionRequest(workingDirectory, "CBBE", outputDirectory));

            Assert.True(result.Success);
            var step = result.Steps.FirstOrDefault(s => s.StartsWith("weight-variants:", StringComparison.Ordinal));
            Assert.NotNull(step);
            Assert.Contains("pairs=1", step, StringComparison.Ordinal);
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }
}

/// <summary>
/// Synchronous <see cref="IProgress{T}"/> implementation that invokes the callback inline
/// on the reporting thread instead of posting it to a <see cref="System.Threading.SynchronizationContext"/>.
/// Use in tests to avoid the non-deterministic scheduling of <see cref="Progress{T}"/>.
/// </summary>
internal sealed class SynchronousProgress<T>(Action<T> handler) : IProgress<T>
{
    public void Report(T value) => handler(value);
}

public sealed class BsdSliderDataTests
{
    [Fact]
    public void BsdMorphReader_ReadsPayloadHeaderAndDeltas()
    {
        var bytes = BuildBsdPayload("PayloadWaist", isHighWeight: true, [(0.125f, -0.25f, 0.375f), (0.5f, 0.625f, -0.75f)]);

        var ok = BsdMorphReader.TryRead(bytes, out var payload);

        Assert.True(ok);
        Assert.NotNull(payload);
        Assert.Equal("PayloadWaist", payload!.SliderName);
        Assert.True(payload.IsHighWeight);
        Assert.Equal(2, payload.VertexCount);
        Assert.Equal(0.125f, payload.Deltas[0].X, 3);
        Assert.Equal(-0.75f, payload.Deltas[1].Z, 3);
    }

    [Fact]
    public void BsdMorphReader_WithTrailingBytes_IsRejected()
    {
        byte[] bytes = [.. BuildBsdPayload("PayloadWaist", isHighWeight: false, [(0.125f, -0.25f, 0.375f)]), (byte)0x01, 0x02, 0x03];

        Assert.False(BsdMorphReader.TryRead(bytes, out _));
    }

    [Fact]
    public void OsdMorphReader_ReadsSparsePayloadHeaderAndDeltas()
    {
        var bytes = BuildOsdPayload(
            ("PayloadWaist", [(0, 0.125f, -0.25f, 0.375f), (2, 0.5f, 0.625f, -0.75f)]),
            ("HideCape_1", [(1, 0.25f, 0f, 0.5f)]));

        var ok = OsdMorphReader.TryRead(bytes, out var payload);

        Assert.True(ok);
        Assert.NotNull(payload);
        Assert.Equal(3, payload!.InferredVertexCount);
        Assert.Equal(2, payload.Morphs.Count);
        Assert.Equal("PayloadWaist", payload.Morphs[0].Name);
        Assert.Equal(2, payload.Morphs[0].SparseDeltas.Count);
        Assert.Equal(2, payload.Morphs[0].SparseDeltas[1].Index);
        Assert.Equal(-0.75f, payload.Morphs[0].SparseDeltas[1].Z, 3);
        Assert.Equal("HideCape_1", payload.Morphs[1].Name);
    }

    [Fact]
    public void OsdMorphReader_ReadsOutfitStudioStylePayloadHeaderAndDeltas()
    {
        var bytes = BuildOutfitStudioOsdPayload(
            version: 1,
            ("PayloadWaist", [(0, 0.125f, -0.25f, 0.375f), (2, 0.5f, 0.625f, -0.75f)]),
            ("HideCape_1", [(1, 0.25f, 0f, 0.5f)]));

        var ok = OsdMorphReader.TryRead(bytes, out var payload);

        Assert.True(ok);
        Assert.NotNull(payload);
        Assert.Equal(3, payload!.InferredVertexCount);
        Assert.Equal(2, payload.Morphs.Count);
        Assert.Equal("PayloadWaist", payload.Morphs[0].Name);
        Assert.Equal(2, payload.Morphs[0].SparseDeltas.Count);
        Assert.Equal(2, payload.Morphs[0].SparseDeltas[1].Index);
        Assert.Equal(-0.75f, payload.Morphs[0].SparseDeltas[1].Z, 3);
        Assert.Equal("HideCape_1", payload.Morphs[1].Name);
    }

    [Fact]
    public void OsdMorphReader_ReadsHigherVersionOutfitStudioPayloadsWithEmptyMorphEntries()
    {
        var bytes = BuildOutfitStudioOsdPayload(
            version: 3,
            ("PayloadWaist", [(0, 0.125f, -0.25f, 0.375f), (2, 0.5f, 0.625f, -0.75f)]),
            ("UnusedMorph", []),
            ("HideCape_1", [(1, 0.25f, 0f, 0.5f)]));

        var ok = OsdMorphReader.TryRead(bytes, out var payload);

        Assert.True(ok);
        Assert.NotNull(payload);
        Assert.Equal(3, payload!.InferredVertexCount);
        Assert.Equal(3, payload.Morphs.Count);
        Assert.Equal("UnusedMorph", payload.Morphs[1].Name);
        Assert.Empty(payload.Morphs[1].SparseDeltas);
        Assert.Equal("HideCape_1", payload.Morphs[2].Name);
    }

    [Fact]
    public void OsdMorphReader_ReadsFixtureBackedLegacyAndOutfitStudioPayloads()
    {
        var legacyPath = GetFixtureFilePath("SampledOsdPayloads", "traveler-legacy.osd");
        var outfitStudioPath = GetFixtureFilePath("SampledOsdPayloads", "traveler-outfitstudio-v1.osd");

        Assert.True(OsdMorphReader.TryRead(legacyPath, out var legacyPayload));
        Assert.NotNull(legacyPayload);
        Assert.Equal(2, legacyPayload!.Morphs.Count);
        Assert.Equal("TravelerWaist", legacyPayload.Morphs[0].Name);
        Assert.Equal(3, legacyPayload.InferredVertexCount);

        Assert.True(OsdMorphReader.TryRead(outfitStudioPath, out var outfitStudioPayload));
        Assert.NotNull(outfitStudioPayload);
        Assert.Equal(2, outfitStudioPayload!.Morphs.Count);
        Assert.Equal("TravelerWaist_1", outfitStudioPayload.Morphs[1].Name);
        Assert.Equal(0.375f, outfitStudioPayload.Morphs[1].SparseDeltas[0].X, 3);
    }

    [Fact]
    public void OsdMorphReader_AllowsTrailingZeroPaddingInFixturePayload()
    {
        var paddedFixturePath = GetFixtureFilePath("SampledOsdPayloads", "traveler-outfitstudio-v3-padded.osd");

        Assert.True(OsdMorphReader.TryRead(paddedFixturePath, out var payload));
        Assert.NotNull(payload);
        Assert.Equal(3, payload!.Morphs.Count);
        Assert.Equal("UnusedMorph", payload.Morphs[1].Name);
        Assert.Empty(payload.Morphs[1].SparseDeltas);
        Assert.Equal("HideCape_1", payload.Morphs[2].Name);
    }

    [Fact]
    public void OsdMorphReader_RecoversFixtureWithUnnamedMorphEntries()
    {
        var malformedFixturePath = GetFixtureFilePath("SampledOsdPayloads", "traveler-outfitstudio-empty-name.osd");

        Assert.True(OsdMorphReader.TryRead(malformedFixturePath, out var payload));
        Assert.NotNull(payload);
        Assert.Equal(2, payload!.Morphs.Count);
        Assert.Equal(string.Empty, payload.Morphs[0].Name);
        Assert.Single(payload.Morphs[0].SparseDeltas);
        Assert.Equal("TravelerWaist", payload.Morphs[1].Name);
        Assert.Equal(4, payload.InferredVertexCount);
    }

    [Fact]
    public void OsdMorphReader_WithTruncatedOutfitStudioPayload_IsRejected()
    {
        var bytes = BuildOutfitStudioOsdPayload(
            version: 1,
            ("PayloadWaist", [(0, 0.125f, -0.25f, 0.375f)]));

