                <OutputFile gender="f" use="true">traveler_armor_0.nif</OutputFile>
                <Slider name="TravelerWaist" />
              </SliderSet>
            </SliderSetInfo>
            """);
        await File.WriteAllBytesAsync(osdPath, BuildOsdPayload(
            ("TravelerWaist", [(0, 0.125f, 0f, 0f), (2, 0.25f, 0.05f, -0.025f)]),
