            Assert.False(resolved.SourceAssetSupport.HasBsdPayloads);
            Assert.DoesNotContain("morph-payloads", resolved.SourceAssetSupport.MissingAssets ?? []);
            Assert.NotNull(resolved.ReusableMorphPayloads);
