    [Fact]
    public async Task BodySlideSourceSupport_WithMalformedUnnamedMorphFixture_IgnoresUnnamedEntriesAndKeepsValidPayloads()
    {
        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var meshDirectory = Path.Combine(workingDirectory, "meshes", "armor", "traveler");
        var sliderSetDirectory = Path.Combine(workingDirectory, "CalienteTools", "BodySlide", "SliderSets");
        var shapeDataDirectory = Path.Combine(workingDirectory, "CalienteTools", "BodySlide", "ShapeData", "TravelerProject");
        Directory.CreateDirectory(meshDirectory);
        Directory.CreateDirectory(sliderSetDirectory);
        Directory.CreateDirectory(shapeDataDirectory);

        var meshPath = Path.Combine(meshDirectory, "traveler_armor_0.nif");
        var ospPath = Path.Combine(sliderSetDirectory, "traveler_pack.osp");
        var osdPath = Path.Combine(shapeDataDirectory, "TravelerProject.osd");
        var referencePath = Path.Combine(shapeDataDirectory, "reference_body.nif");

        File.Copy(GetFixtureFilePath("SampledBodySlideShapeDataPack", Path.Combine("meshes", "armor", "traveler", "traveler_armor_0.nif")), meshPath);
        File.Copy(GetFixtureFilePath("SampledOsdPayloads", "traveler-outfitstudio-empty-name.osd"), osdPath);
        File.Copy(GetFixtureFilePath("SampledBodySlideShapeDataPack", Path.Combine("CalienteTools", "BodySlide", "ShapeData", "TravelerProject", "reference_body.nif")), referencePath);
        await File.WriteAllTextAsync(
            ospPath,
            """
            <SliderSetInfo version="1">
              <SliderSet name="TravelerProject" set="3BA">
                <OutputPath>meshes\armor\traveler\</OutputPath>
                <OutputFile gender="f" use="true">traveler_armor_0.nif</OutputFile>
                <Slider name="TravelerWaist" />
              </SliderSet>
            </SliderSetInfo>
            """);

        try
        {
            var armor = new ImportedArmor(meshPath, [meshPath], [], [], []);
            var resolved = await BodySlideSourceProjectSupport.ResolveAsync(armor, "CBBE", CancellationToken.None);

            Assert.Contains("TravelerWaist", resolved.Sliders);
            Assert.DoesNotContain(string.Empty, resolved.Sliders);
            Assert.NotNull(resolved.ReusableMorphPayloads);
            Assert.True(resolved.ReusableMorphPayloads!.ContainsKey("TravelerWaist"));
            Assert.False(resolved.ReusableMorphPayloads.ContainsKey(string.Empty));
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }

    [Fact]
    public async Task ConvertAsync_WithDefaultModules_WritesBsdSliderFiles()
    {
        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var outputDirectory = Path.Combine(workingDirectory, "output");
        Directory.CreateDirectory(workingDirectory);
        var inputFile = Path.Combine(workingDirectory, "cuirass.nif");
        await File.WriteAllTextAsync(inputFile, "mesh");

        try
        {
            var orchestrator = StandaloneConversionModules.CreateDefault();
            var result = await orchestrator.ConvertAsync(new ConversionRequest(inputFile, "3BA", outputDirectory));

            Assert.True(result.Success);

            // BSD files land in CalienteTools/BodySlide/ShapeData/<ProjectName>/
            var shapeDataDir = Directory.GetDirectories(outputDirectory, "*", SearchOption.AllDirectories)
                .FirstOrDefault(d => d.Contains("ShapeData", StringComparison.OrdinalIgnoreCase));
            Assert.NotNull(shapeDataDir);

            var bsdFiles = Directory.GetFiles(shapeDataDir!, "*.bsd", SearchOption.AllDirectories);
            Assert.NotEmpty(bsdFiles);

            // Verify BSD magic header in each file.
            foreach (var bsdFile in bsdFiles)
            {
                var header = await File.ReadAllBytesAsync(bsdFile);
                Assert.True(header.Length >= 4);
                Assert.Equal(0x42, header[0]); // 'B'
                Assert.Equal(0x53, header[1]); // 'S'
                Assert.Equal(0x44, header[2]); // 'D'
                Assert.Equal(0x00, header[3]); // null
            }
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }

    [Fact]
    public async Task ConvertAsync_WithDefaultModules_WritesBsdForLowAndHighWeight()
    {
        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var outputDirectory = Path.Combine(workingDirectory, "output");
        Directory.CreateDirectory(workingDirectory);
        var inputFile = Path.Combine(workingDirectory, "armor.nif");
        await File.WriteAllTextAsync(inputFile, "mesh");

        try
        {
            var orchestrator = StandaloneConversionModules.CreateDefault();
            var result = await orchestrator.ConvertAsync(new ConversionRequest(inputFile, "CBBE", outputDirectory));

            Assert.True(result.Success);
            var shapeDataDir = Directory.GetDirectories(outputDirectory, "*", SearchOption.AllDirectories)
                .FirstOrDefault(d => d.Contains("ShapeData", StringComparison.OrdinalIgnoreCase));
            Assert.NotNull(shapeDataDir);

            var bsdFiles = Directory.GetFiles(shapeDataDir!, "*.bsd", SearchOption.AllDirectories).Select(Path.GetFileName).ToHashSet(StringComparer.OrdinalIgnoreCase);

            // Expect both low-weight (e.g. "Belly.bsd") and high-weight (e.g. "Belly_1.bsd") files.
            Assert.True(bsdFiles.Any(f => !f!.EndsWith("_1.bsd", StringComparison.OrdinalIgnoreCase)), "Expected low-weight .bsd files.");
            Assert.True(bsdFiles.Any(f => f!.EndsWith("_1.bsd", StringComparison.OrdinalIgnoreCase)), "Expected high-weight _1.bsd files.");
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }

    [Fact]
    public async Task ConvertAsync_WithDefaultModules_BsdFilesContainVertexDeltaPayload()
    {
        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var outputDirectory = Path.Combine(workingDirectory, "output");
        Directory.CreateDirectory(workingDirectory);
        var inputFile = Path.Combine(workingDirectory, "gauntlets.nif");
        await File.WriteAllTextAsync(inputFile, "mesh");

        try
        {
            var orchestrator = StandaloneConversionModules.CreateDefault();
            var result = await orchestrator.ConvertAsync(new ConversionRequest(inputFile, "CBBE", outputDirectory));

            Assert.True(result.Success);
            var bsdFile = Directory.GetFiles(outputDirectory, "*.bsd", SearchOption.AllDirectories).First();
            var bytes = await File.ReadAllBytesAsync(bsdFile);

            var nameLengthOffset = 7;
            var sliderNameLength = BitConverter.ToUInt16(bytes, nameLengthOffset);
            var vertexCountOffset = nameLengthOffset + sizeof(ushort) + sliderNameLength;
            var vertexCount = BitConverter.ToUInt32(bytes, vertexCountOffset);
            var deltaOffset = vertexCountOffset + sizeof(uint);
            var expectedDeltaBytes = checked((int)vertexCount * 12);

            Assert.True(vertexCount > 0, "BSD vertex count should be populated.");
            Assert.Equal(deltaOffset + expectedDeltaBytes, bytes.Length);
            Assert.Contains(bytes.AsSpan(deltaOffset, expectedDeltaBytes).ToArray(), b => b != 0);
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }

    private static string GetFixtureFilePath(string fixtureName, string relativeFilePath, [CallerFilePath] string currentFilePath = "")
    {
        return Path.Combine(
            Path.GetDirectoryName(currentFilePath)!,
            "Fixtures",
            fixtureName,
            relativeFilePath);
    }

    private static byte[] BuildBsdPayload(string sliderName, bool isHighWeight, IReadOnlyList<(float X, float Y, float Z)> deltas)
    {
        var nameBytes = System.Text.Encoding.UTF8.GetBytes(sliderName);
        using var ms = new MemoryStream();
        using var writer = new BinaryWriter(ms, System.Text.Encoding.UTF8, leaveOpen: true);
        writer.Write((byte)'B');
        writer.Write((byte)'S');
        writer.Write((byte)'D');
        writer.Write((byte)0);
        writer.Write((ushort)1);
        writer.Write(isHighWeight ? (byte)1 : (byte)0);
        writer.Write((ushort)nameBytes.Length);
        writer.Write(nameBytes);
        writer.Write((uint)deltas.Count);
        foreach (var (x, y, z) in deltas)
        {
            writer.Write(x);
            writer.Write(y);
            writer.Write(z);
        }

        return ms.ToArray();
    }

    private static byte[] BuildOsdPayload(params (string Name, IReadOnlyList<(int Index, float X, float Y, float Z)> Deltas)[] morphs)
    {
        using var ms = new MemoryStream();
        using var writer = new BinaryWriter(ms, System.Text.Encoding.UTF8, leaveOpen: true);
        writer.Write(new byte[] { 0x4f, 0x53, 0x44, 0x01 });
        writer.Write(morphs.Length);
        foreach (var morph in morphs)
        {
            var nameBytes = System.Text.Encoding.UTF8.GetBytes(morph.Name);
            writer.Write((byte)nameBytes.Length);
            writer.Write(nameBytes);
            writer.Write((ushort)morph.Deltas.Count);
            foreach (var (index, x, y, z) in morph.Deltas)
            {
                writer.Write((ushort)index);
                writer.Write(x);
                writer.Write(y);
                writer.Write(z);
            }
        }

        return ms.ToArray();
    }

    private static byte[] BuildOutfitStudioOsdPayload(uint version, params (string Name, IReadOnlyList<(int Index, float X, float Y, float Z)> Deltas)[] morphs)
    {
        using var ms = new MemoryStream();
        using var writer = new BinaryWriter(ms, System.Text.Encoding.UTF8, leaveOpen: true);
        writer.Write(new byte[] { 0x4f, 0x53, 0x44, 0x00 });
        writer.Write(version);
        writer.Write(morphs.Length);
        foreach (var morph in morphs)
        {
            var nameBytes = System.Text.Encoding.UTF8.GetBytes(morph.Name);
            writer.Write((byte)nameBytes.Length);
            writer.Write(nameBytes);
            writer.Write((ushort)morph.Deltas.Count);
            foreach (var (index, x, y, z) in morph.Deltas)
            {
                writer.Write((ushort)index);
                writer.Write(x);
                writer.Write(y);
                writer.Write(z);
            }
        }

        return ms.ToArray();
    }

    public sealed class TriMorphFileTests
    {
        [Fact]
        public void TriMorphReader_ReadsMorphNamesAndDeltaPayloads()
        {
            var bytes = BuildTriPayload(
                vertexCount: 2,
                ("BreastLift", [(0.125f, 0f, -0.25f), (0.5f, 0.25f, 0.125f)]),
                ("HideCape_1", [(0f, 0f, 0f), (0.25f, -0.25f, 0.5f)]));

            var ok = TriMorphReader.TryRead(bytes, out var payload);

            Assert.True(ok);
            Assert.NotNull(payload);
            Assert.Equal(2, payload!.VertexCount);
            Assert.Equal(2, payload.Morphs.Count);
            Assert.Equal("BreastLift", payload.Morphs[0].Name);
            Assert.Equal(0.125f, payload.Morphs[0].Deltas[0].X, 3);
            Assert.Equal("HideCape_1", payload.Morphs[1].Name);
            Assert.Equal(0.5f, payload.Morphs[1].Deltas[1].Z, 3);
        }

        [Fact]
        public void TriMorphReader_ReadsLegacyFrtri002MorphNamesAndDeltaPayloads()
        {
            var bytes = BuildTriPayloadFrtri002(
                vertexCount: 2,
                ("BreastLift", [(0.125f, 0f, -0.25f), (0.5f, 0.25f, 0.125f)]),
