    [Fact]
    public async Task ConvertAsync_WithDefaultModules_TriFilesContainMorphDeltaPayload()
    {
        var workingDirectory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var outputDirectory = Path.Combine(workingDirectory, "output");
        Directory.CreateDirectory(workingDirectory);
        var inputFile = Path.Combine(workingDirectory, "helmet.nif");
        await File.WriteAllTextAsync(inputFile, "mesh");

        try
        {
            var orchestrator = StandaloneConversionModules.CreateDefault();
            var result = await orchestrator.ConvertAsync(new ConversionRequest(inputFile, "3BA", outputDirectory));

            Assert.True(result.Success);
            var triFile = Directory.GetFiles(outputDirectory, "*.tri", SearchOption.AllDirectories).First();
            var bytes = await File.ReadAllBytesAsync(triFile);

            var offset = 8;
            var vertexCount = BitConverter.ToUInt32(bytes, offset);
            offset += sizeof(uint);
            var morphCount = BitConverter.ToUInt32(bytes, offset);
            offset += sizeof(uint);

            Assert.True(vertexCount > 0, "TRI vertex count should be populated.");
            Assert.True(morphCount > 0, "TRI should include morph entries.");

            for (var index = 0; index < morphCount; index++)
            {
                var nameLength = BitConverter.ToUInt16(bytes, offset);
                offset += sizeof(ushort) + nameLength;
                var deltaCount = BitConverter.ToUInt32(bytes, offset);
                offset += sizeof(uint);
                Assert.Equal(vertexCount, deltaCount);
            }

            var expectedPayloadBytes = checked((int)morphCount * (int)vertexCount * 6);
            Assert.Equal(offset + expectedPayloadBytes, bytes.Length);
            Assert.Contains(bytes.AsSpan(offset, expectedPayloadBytes).ToArray(), b => b != 0);
        }
        finally
        {
            Directory.Delete(workingDirectory, recursive: true);
        }
    }

    private static byte[] BuildTriPayload(int vertexCount, params (string Name, IReadOnlyList<(float X, float Y, float Z)> Deltas)[] morphs)
    {
        using var ms = new MemoryStream();
        using var writer = new BinaryWriter(ms, System.Text.Encoding.UTF8, leaveOpen: true);
        writer.Write(System.Text.Encoding.ASCII.GetBytes("FRTRI003"));
        writer.Write((uint)vertexCount);
        writer.Write((uint)morphs.Length);

        foreach (var morph in morphs)
        {
            var nameBytes = System.Text.Encoding.UTF8.GetBytes(morph.Name);
            writer.Write((ushort)nameBytes.Length);
            writer.Write(nameBytes);
            writer.Write((uint)morph.Deltas.Count);
        }

        foreach (var morph in morphs)
        {
            foreach (var (x, y, z) in morph.Deltas)
            {
                writer.Write((short)Math.Round(x * 2048f));
                writer.Write((short)Math.Round(y * 2048f));
                writer.Write((short)Math.Round(z * 2048f));
            }
        }

        return ms.ToArray();
    }

    private static byte[] BuildIndexedTriPayload(int vertexCount, params (string Name, IReadOnlyList<(int Index, float X, float Y, float Z)> Deltas)[] morphs)
    {
        using var ms = new MemoryStream();
        using var writer = new BinaryWriter(ms, System.Text.Encoding.UTF8, leaveOpen: true);
        writer.Write(System.Text.Encoding.ASCII.GetBytes("FRTRI003"));
        writer.Write((uint)vertexCount);
        writer.Write((uint)morphs.Length);

        foreach (var morph in morphs)
        {
            var nameBytes = System.Text.Encoding.UTF8.GetBytes(morph.Name);
            writer.Write((ushort)nameBytes.Length);
            writer.Write(nameBytes);
            writer.Write((uint)morph.Deltas.Count);
        }

        foreach (var morph in morphs)
        {
            foreach (var (index, x, y, z) in morph.Deltas)
            {
                writer.Write((ushort)index);
                writer.Write((short)Math.Round(x * 2048f));
                writer.Write((short)Math.Round(y * 2048f));
                writer.Write((short)Math.Round(z * 2048f));
            }
        }

        return ms.ToArray();
    }

    private static byte[] BuildTriPayloadFrtri002(int vertexCount, params (string Name, IReadOnlyList<(float X, float Y, float Z)> Deltas)[] morphs)
    {
        using var ms = new MemoryStream();
        using var writer = new BinaryWriter(ms, System.Text.Encoding.UTF8, leaveOpen: true);
        writer.Write(System.Text.Encoding.ASCII.GetBytes("FRTRI002"));
        writer.Write((uint)vertexCount);
        writer.Write((uint)morphs.Length);

        foreach (var morph in morphs)
        {
            var nameBytes = System.Text.Encoding.UTF8.GetBytes(morph.Name);
            writer.Write((ushort)nameBytes.Length);
            writer.Write(nameBytes);
            writer.Write((uint)morph.Deltas.Count);
        }

        foreach (var morph in morphs)
        {
            foreach (var (x, y, z) in morph.Deltas)
            {
                writer.Write(x);
                writer.Write(y);
                writer.Write(z);
            }
        }

        return ms.ToArray();
    }

    private static byte[] BuildPirtPayload(string shapeName, int vertexCount, params (string Name, IReadOnlyList<(float X, float Y, float Z)> Deltas)[] morphs)
    {
        using var ms = new MemoryStream();
        using var writer = new BinaryWriter(ms, System.Text.Encoding.UTF8, leaveOpen: true);
        writer.Write(System.Text.Encoding.ASCII.GetBytes("PIRT"));
        writer.Write((ushort)1);
        var shapeNameBytes = System.Text.Encoding.UTF8.GetBytes(shapeName);
        writer.Write((byte)shapeNameBytes.Length);
        writer.Write(shapeNameBytes);
        writer.Write((ushort)morphs.Length);

        foreach (var morph in morphs)
        {
            var morphNameBytes = System.Text.Encoding.UTF8.GetBytes(morph.Name);
            writer.Write((byte)morphNameBytes.Length);
            writer.Write(morphNameBytes);

            var deltaRows = Enumerable.Range(0, Math.Min(vertexCount, morph.Deltas.Count))
                .Where(index =>
                {
                    var (x, y, z) = morph.Deltas[index];
                    return Math.Abs(x) > 0.00001f || Math.Abs(y) > 0.00001f || Math.Abs(z) > 0.00001f;
                })
                .Select(index => (Index: index, Delta: morph.Deltas[index]))
                .ToList();

            var maxAbs = deltaRows.Count == 0
                ? 0f
                : deltaRows.Max(static row => Math.Max(Math.Abs(row.Delta.X), Math.Max(Math.Abs(row.Delta.Y), Math.Abs(row.Delta.Z))));
            var multiplier = maxAbs <= 0.000001f ? 1f : maxAbs / 32767f;
            writer.Write(multiplier);
            writer.Write((ushort)deltaRows.Count);
            foreach (var row in deltaRows)
            {
                writer.Write((ushort)row.Index);
                writer.Write((short)Math.Round(row.Delta.X / multiplier));
                writer.Write((short)Math.Round(row.Delta.Y / multiplier));
                writer.Write((short)Math.Round(row.Delta.Z / multiplier));
            }
        }

        return ms.ToArray();
    }

}

public sealed class BodySignatureVertexCountTests
{
    [Theory]
    [InlineData("CBBE",  6942)] // within 6800-7100
    [InlineData("UNP",   6032)] // within 5900-6200
    [InlineData("UUNP",  9000)] // within 8200-9800
    [InlineData("COCO CBBE", 9800)] // within 9000-10400
    [InlineData("COCO UUNP", 10032)] // within 9400-10800
    [InlineData("HIMBO", 6820)] // within 6600-7100
    [InlineData("BHUNP", 10080)] // within 9800-10400
    [InlineData("3BA",   10032)] // within 9800-10400
    [InlineData("TBD",   7680)] // within 7400-7900
    [InlineData("SAM",   5984)] // within 5800-6200
    [InlineData("SOS",   6274)] // within 6100-6500
    [InlineData("TNG",   6640)] // within 6400-6900
    [InlineData("UBE",   7000)] // within 6800-7200
    [InlineData("Vanilla", 5000)] // within 4000-6100
    public void BodySignatureTemplate_VertexCountRanges_IncludeTypicalCounts(string bodyName, int typicalCount)
    {
        var template = VanillaBodySignatureDatabase.Templates
            .First(t => string.Equals(t.Body, bodyName, StringComparison.OrdinalIgnoreCase));

        Assert.True(template.VertexCountMin > 0, $"{bodyName} should have a non-zero VertexCountMin.");
        Assert.True(template.VertexCountMax > template.VertexCountMin, $"{bodyName} VertexCountMax should exceed Min.");
        Assert.InRange(typicalCount, template.VertexCountMin, template.VertexCountMax);
    }

    [Fact]
    public void AllTemplates_HaveVertexCountRanges()
    {
        Assert.All(VanillaBodySignatureDatabase.Templates, t =>
        {
            Assert.True(t.VertexCountMin > 0,   $"{t.Body} is missing VertexCountMin.");
            Assert.True(t.VertexCountMax > t.VertexCountMin, $"{t.Body} VertexCountMax must exceed Min.");
        });
    }

    [Fact]
    public void AllTemplates_HaveBoundingRatioRanges()
    {
        Assert.All(VanillaBodySignatureDatabase.Templates, t =>
        {
            Assert.True(t.HeightToWidthRatioMin > 0, $"{t.Body} should define HeightToWidthRatioMin.");
            Assert.True(t.HeightToWidthRatioMax > t.HeightToWidthRatioMin, $"{t.Body} HeightToWidthRatioMax must exceed Min.");
            Assert.True(t.DepthToWidthRatioMin > 0, $"{t.Body} should define DepthToWidthRatioMin.");
            Assert.True(t.DepthToWidthRatioMax > t.DepthToWidthRatioMin, $"{t.Body} DepthToWidthRatioMax must exceed Min.");
        });
    }

