                [],
                1);

            var pluginAnalysis = new PluginAnalysisResult(
                ["LegacyArmor.esp [ESP; confidence=1.00]"],
                [
                    new PluginArmorAddon(
                        "LegacyArmor.esp [ESP; confidence=1.00]",
                        ["meshes/armor/iron/ironarmor_0.nif"],
                        FormId: 0x00000802u,
                        EditorId: "LegacyAddon",
