    [Fact]
    public void SkeletonRemapSafetyClassifier_AllowsStrongSparseMatchToBeSafe()
    {
        var candidates = new[]
        {
            new SkeletonInferenceCandidate(
                "ube-extended",
                0.96d,
                ["semantic-overlap:3", "ecosystem-cues:2", "chain-depth:3"],
                true),
            new SkeletonInferenceCandidate(
                "digitigrade-beast",
                0.62d,
                ["semantic-overlap:1", "ecosystem-cues:1"],
                true)
        };

        var safety = SkeletonRemapSafetyClassifier.BuildSafety(
            mappedBoneCount: 14,
            unsupportedBoneCount: 0,
            sourceSkeletonConfidence: 0.96d,
            usedSparseInference: true,
            sourceSkeletonCandidates: candidates);
        var signals = SkeletonRemapSafetyClassifier.BuildSignals(
            mappedBoneCount: 14,
            unsupportedBoneCount: 0,
            sourceSkeletonConfidence: 0.96d,
            usedSparseInference: true,
            sourceSkeletonCandidates: candidates,
            remapSafety: safety);

        Assert.Equal("safe", safety);
        Assert.Contains("strong-sparse-framework", signals);
        Assert.Contains("sparse-inference", signals);
    }

    [Fact]
    public void SkeletonRemapSafetyClassifier_KeepsWeakSparseMatchProvisional()
    {
        var candidates = new[]
        {
            new SkeletonInferenceCandidate(
                "ube-extended",
                0.84d,
                ["semantic-overlap:2", "ecosystem-cues:1", "chain-depth:1"],
                true),
            new SkeletonInferenceCandidate(
                "digitigrade-beast",
                0.68d,
                ["semantic-overlap:1", "ecosystem-cues:1"],
                true)
        };

        var safety = SkeletonRemapSafetyClassifier.BuildSafety(
            mappedBoneCount: 14,
            unsupportedBoneCount: 0,
            sourceSkeletonConfidence: 0.84d,
            usedSparseInference: true,
            sourceSkeletonCandidates: candidates);

        Assert.Equal("provisional", safety);
    }

    [Fact]
    public void SkeletonRemapSafetyClassifier_RequiresVeryStrongSparseEvidenceForSafe()
    {
        var candidates = new[]
        {
            new SkeletonInferenceCandidate(
                "ube-extended",
                0.93d,
                ["semantic-overlap:2", "ecosystem-cues:2", "chain-depth:2"],
                true),
            new SkeletonInferenceCandidate(
                "digitigrade-beast",
                0.66d,
                ["semantic-overlap:1", "ecosystem-cues:1"],
                true)
        };

        var safety = SkeletonRemapSafetyClassifier.BuildSafety(
            mappedBoneCount: 14,
            unsupportedBoneCount: 0,
            sourceSkeletonConfidence: 0.93d,
            usedSparseInference: true,
            sourceSkeletonCandidates: candidates);

        Assert.Equal("provisional", safety);
    }

    [Fact]
    public void SkeletonRemapSafetyClassifier_DowngradesVeryWeakSparseMatchToUnsafe()
    {
        var candidates = new[]
        {
            new SkeletonInferenceCandidate(
                "custom-beast-rig",
                0.69d,
                ["semantic-overlap:1", "ecosystem-cues:1"],
                true),
            new SkeletonInferenceCandidate(
                "digitigrade-beast",
                0.51d,
                ["semantic-overlap:1"],
                true)
        };

        var safety = SkeletonRemapSafetyClassifier.BuildSafety(
            mappedBoneCount: 12,
            unsupportedBoneCount: 0,
            sourceSkeletonConfidence: 0.69d,
            usedSparseInference: true,
            sourceSkeletonCandidates: candidates);
        var signals = SkeletonRemapSafetyClassifier.BuildSignals(
            mappedBoneCount: 12,
            unsupportedBoneCount: 0,
            sourceSkeletonConfidence: 0.69d,
            usedSparseInference: true,
            sourceSkeletonCandidates: candidates,
            remapSafety: safety);

        Assert.Equal("unsafe", safety);
        Assert.Contains("weak-sparse-framework", signals);
        Assert.Contains("semantic-overlap:1", signals);
        Assert.Contains("framework-cues:1", signals);
    }
}

