    [Fact]
    public async Task AnalyzeAsync_AmbiguousEspWithFeReferencedMasterChain_ReclassifiesAsEspfe()
    {
        var dir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);

        try
        {
            static byte[] BuildRecord(string tag, byte[] data, uint formId = 0u)
            {
                var header = new byte[24 + data.Length];
                System.Text.Encoding.ASCII.GetBytes(tag.PadRight(4)[..4]).CopyTo(header, 0);
                BitConverter.TryWriteBytes(header.AsSpan(4), (uint)data.Length);
                BitConverter.TryWriteBytes(header.AsSpan(12), formId);
                data.CopyTo(header, 24);
                return header;
            }

            static byte[] BuildPluginWithMastersForContext(IReadOnlyList<string> masters, params byte[][] records)
            {
                using var ms = new MemoryStream();
                ms.Write(BuildSubrecord("HEDR", new byte[12]));
                ms.Write(BuildSubrecord("CNAM", [0x00]));
                foreach (var master in masters)
                {
                    ms.Write(BuildSubrecord("MAST", System.Text.Encoding.ASCII.GetBytes(master + "\0")));
                    ms.Write(BuildSubrecord("DATA", new byte[8]));
                }

                var plugin = new List<byte>(BuildRecord("TES4", ms.ToArray()));
                plugin.AddRange(records.SelectMany(static record => record));
                return [.. plugin];
            }

            var sourcePluginPath = Path.Combine(dir, "ContextualLightParent.esp");
            var childPluginPath = Path.Combine(dir, "ContextualLightChild.esp");

            await File.WriteAllBytesAsync(
                sourcePluginPath,
                BuildPluginWithArmaFormId(0x00000200u, 0x00000801u));

            var childArmoData = BuildSubrecord("EDID", System.Text.Encoding.ASCII.GetBytes("ContextualLightArmor\0"))
                .Concat(BuildSubrecord("ARMA", BitConverter.GetBytes(0xFE000801u)))
                .ToArray();
            var childArmo = BuildRecord("ARMO", childArmoData, formId: 0x00001234u);
            await File.WriteAllBytesAsync(childPluginPath, BuildPluginWithMastersForContext(["ContextualLightParent.esp"], childArmo));

            var service = new BasicPluginAnalysisService();
            var analysis = await service.AnalyzeAsync(
                new ImportedArmor(dir, [], [], [], []),
                "CBBE",
                CancellationToken.None);

            Assert.DoesNotContain("ContextualLightParent.esp", analysis.AmbiguousPlugins ?? []);
            Assert.Contains(analysis.ScannedPlugins, plugin => plugin.Contains("ContextualLightParent.esp [ESPFE;", StringComparison.OrdinalIgnoreCase));
            Assert.DoesNotContain("AMBIGUOUS", string.Join('\n', analysis.ScannedPlugins), StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("AMBIGUOUS", analysis.PatchGuidance, StringComparison.OrdinalIgnoreCase);
        }
        finally
        {
            Directory.Delete(dir, recursive: true);
        }
    }

    [Fact]
    public async Task AnalyzeAsync_AmbiguousEspWithFeOwnedOverrideContext_ReclassifiesAsEspfe()
    {
        var dir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);

        try
        {
            byte[] BuildRecord(string tag, byte[] data, uint formId = 0u)
            {
                var header = new byte[24 + data.Length];
                System.Text.Encoding.ASCII.GetBytes(tag.PadRight(4)[..4]).CopyTo(header, 0);
                BitConverter.TryWriteBytes(header.AsSpan(4), (uint)data.Length);
                BitConverter.TryWriteBytes(header.AsSpan(12), formId);
                data.CopyTo(header, 24);
                return header;
            }

            byte[] BuildPluginWithMastersForContext(IReadOnlyList<string> masters, params byte[][] records)
            {
                using var ms = new MemoryStream();
                ms.Write(BuildSubrecord("HEDR", new byte[12]));
                ms.Write(BuildSubrecord("CNAM", [0x00]));
                foreach (var master in masters)
                {
                    ms.Write(BuildSubrecord("MAST", System.Text.Encoding.ASCII.GetBytes(master + "\0")));
                    ms.Write(BuildSubrecord("DATA", new byte[8]));
                }

                var plugin = new List<byte>(BuildRecord("TES4", ms.ToArray()));
                plugin.AddRange(records.SelectMany(static record => record));
                return [.. plugin];
            }

            byte[] BuildLightFlagPluginWithArma(uint tes4Flags, uint armaFormId)
            {
                using var ms = new MemoryStream();
                ms.Write(BuildSubrecord("HEDR", new byte[12]));
                ms.Write(BuildSubrecord("CNAM", [0x00]));
                var tes4 = BuildRecord("TES4", ms.ToArray());
                WriteUInt32Le(tes4, 8, tes4Flags);
                var armaData = BuildSubrecord("EDID", System.Text.Encoding.ASCII.GetBytes("OwnedArmor\0"));
                var arma = BuildRecord("ARMA", armaData, armaFormId);
                return [.. tes4, .. arma];
            }

            var sourcePluginPath = Path.Combine(dir, "ContextualLightOwnedParent.esp");
            var childPluginPath = Path.Combine(dir, "ContextualLightOverrideChild.esp");

            await File.WriteAllBytesAsync(
                sourcePluginPath,
                BuildLightFlagPluginWithArma(0x00000200u, 0x00000801u));

            var childArmaData = BuildSubrecord("EDID", System.Text.Encoding.ASCII.GetBytes("OwnedArmorOverride\0"))
                .Concat(BuildSubrecord("MOD2", System.Text.Encoding.ASCII.GetBytes("meshes/armor/contextual/owned_0.nif\0")))
                .ToArray();
            var childArma = BuildRecord("ARMA", childArmaData, formId: 0xFE000801u);
            await File.WriteAllBytesAsync(
                childPluginPath,
                BuildPluginWithMastersForContext(["ContextualLightOwnedParent.esp"], childArma));

            var service = new BasicPluginAnalysisService();
            var analysis = await service.AnalyzeAsync(
                new ImportedArmor(dir, [], [], [], []),
                "CBBE",
                CancellationToken.None);

            Assert.DoesNotContain("ContextualLightOwnedParent.esp", analysis.AmbiguousPlugins ?? []);
            Assert.Contains(analysis.ScannedPlugins, plugin => plugin.Contains("ContextualLightOwnedParent.esp [ESPFE;", StringComparison.OrdinalIgnoreCase));
            Assert.DoesNotContain("AMBIGUOUS", string.Join('\n', analysis.ScannedPlugins), StringComparison.OrdinalIgnoreCase);
        }
        finally
        {
            Directory.Delete(dir, recursive: true);
        }
    }

    [Fact]
    public async Task AnalyzeAsync_AmbiguousEspWithGrandchildFeOverride_PropagatesEspfeEvidenceAcrossMasterChain()
    {
        var dir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);

        try
        {
            byte[] BuildRecord(string tag, byte[] data, uint formId = 0u)
            {
                var header = new byte[24 + data.Length];
                System.Text.Encoding.ASCII.GetBytes(tag.PadRight(4)[..4]).CopyTo(header, 0);
                BitConverter.TryWriteBytes(header.AsSpan(4), (uint)data.Length);
                BitConverter.TryWriteBytes(header.AsSpan(12), formId);
                data.CopyTo(header, 24);
                return header;
            }

            byte[] BuildPluginWithMastersForContext(IReadOnlyList<string> masters, params byte[][] records)
            {
                using var ms = new MemoryStream();
                ms.Write(BuildSubrecord("HEDR", new byte[12]));
                ms.Write(BuildSubrecord("CNAM", [0x00]));
                foreach (var master in masters)
                {
                    ms.Write(BuildSubrecord("MAST", System.Text.Encoding.ASCII.GetBytes(master + "\0")));
                    ms.Write(BuildSubrecord("DATA", new byte[8]));
                }

                var plugin = new List<byte>(BuildRecord("TES4", ms.ToArray()));
                plugin.AddRange(records.SelectMany(static record => record));
                return [.. plugin];
            }

            byte[] BuildLightFlagPluginWithArma(uint tes4Flags, uint armaFormId, string editorId)
            {
                using var ms = new MemoryStream();
                ms.Write(BuildSubrecord("HEDR", new byte[12]));
                ms.Write(BuildSubrecord("CNAM", [0x00]));
                var tes4 = BuildRecord("TES4", ms.ToArray());
                WriteUInt32Le(tes4, 8, tes4Flags);
                var armaData = BuildSubrecord("EDID", System.Text.Encoding.ASCII.GetBytes(editorId + "\0"));
                var arma = BuildRecord("ARMA", armaData, armaFormId);
                return [.. tes4, .. arma];
            }

            byte[] BuildArmaRecord(uint armaFormId, string editorId)
            {
                var armaData = BuildSubrecord("EDID", System.Text.Encoding.ASCII.GetBytes(editorId + "\0"));
                return BuildRecord("ARMA", armaData, armaFormId);
            }

            var rootPluginPath = Path.Combine(dir, "TransitiveLightRoot.esp");
            var bridgePluginPath = Path.Combine(dir, "TransitiveLightBridge.esp");
            var childPluginPath = Path.Combine(dir, "TransitiveLightGrandchild.esp");

            await File.WriteAllBytesAsync(
                rootPluginPath,
                BuildLightFlagPluginWithArma(0x00000200u, 0x00000801u, "TransitiveRootArmor"));
            await File.WriteAllBytesAsync(
                bridgePluginPath,
                BuildPluginWithMastersForContext(
                    ["TransitiveLightRoot.esp"],
                    BuildArmaRecord(0x01000801u, "TransitiveBridgeArmor")));
            var bridgeBytes = await File.ReadAllBytesAsync(bridgePluginPath);
            WriteUInt32Le(bridgeBytes, 8, 0x00000200u);
            await File.WriteAllBytesAsync(bridgePluginPath, bridgeBytes);

            var childArmaData = BuildSubrecord("EDID", System.Text.Encoding.ASCII.GetBytes("TransitiveBridgeOverride\0"))
                .Concat(BuildSubrecord("MOD2", System.Text.Encoding.ASCII.GetBytes("meshes/armor/contextual/transitive_0.nif\0")))
                .ToArray();
            var childArma = BuildRecord("ARMA", childArmaData, formId: 0xFE000801u);
            await File.WriteAllBytesAsync(
                childPluginPath,
                BuildPluginWithMastersForContext(["TransitiveLightBridge.esp"], childArma));

            var service = new BasicPluginAnalysisService();
            var analysis = await service.AnalyzeAsync(
                new ImportedArmor(dir, [], [], [], []),
                "CBBE",
                CancellationToken.None);

            Assert.DoesNotContain("TransitiveLightRoot.esp", analysis.AmbiguousPlugins ?? []);
            Assert.DoesNotContain("TransitiveLightBridge.esp", analysis.AmbiguousPlugins ?? []);
            Assert.Contains(analysis.ScannedPlugins, plugin => plugin.Contains("TransitiveLightRoot.esp [ESPFE;", StringComparison.OrdinalIgnoreCase));
            Assert.Contains(analysis.ScannedPlugins, plugin => plugin.Contains("TransitiveLightBridge.esp [ESPFE;", StringComparison.OrdinalIgnoreCase));
        }
        finally
        {
            Directory.Delete(dir, recursive: true);
        }
    }

    // ── ARMA subrecord rewrite ────────────────────────────────────────────────

    [Fact]
    public void RewriteArmaSubrecords_NoMatchingPaths_ReturnsBytesUnchanged()
    {
        // Build an ARMA data block with a single EDID subrecord (not a mesh path subrecord).
        const string edid = "MyArmor\0";
        var edidBytes = System.Text.Encoding.ASCII.GetBytes(edid);
        byte[] data = BuildSubrecord("EDID", edidBytes);

        var rewriteMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["meshes/armor/iron/iron_0.nif"] = "meshes/slidesmith/cbbe/iron_0.nif"
        };

        var (newData, rewritten) = BinaryPluginRewriteService.RewriteArmaSubrecords(
            data, 0, data.Length, rewriteMap);

        Assert.Equal(0, rewritten);
        Assert.Equal(data, newData);
    }

    private static byte[] BuildTes4HeaderWithFlags(uint flags)
    {
        var bytes = new byte[24];
        System.Text.Encoding.ASCII.GetBytes("TES4").CopyTo(bytes, 0);
        BitConverter.TryWriteBytes(bytes.AsSpan(8), flags);
        return bytes;
    }

    private static byte[] BuildPluginWithArmaFormId(uint tes4Flags, uint armaFormId)
    {
        return BuildPluginWithArmaFormIds(tes4Flags, armaFormId);
    }

    private static byte[] BuildPluginWithArmaFormIds(uint tes4Flags, params uint[] armaFormIds)
    {
        var pluginBytes = new List<byte>(BuildTes4HeaderWithFlags(tes4Flags));
        foreach (var formId in armaFormIds)
        {
            var armaData = BuildSubrecord("EDID", System.Text.Encoding.ASCII.GetBytes("TestArmor\0"));
            var arma = BuildFlatRecordForTests("ARMA", armaData, formId);
            pluginBytes.AddRange(arma);
        }

        return [.. pluginBytes];
    }

    private static byte[] BuildPluginWithRecordFormIds(uint tes4Flags, string recordTag, params uint[] recordFormIds)
    {
        var pluginBytes = new List<byte>(BuildTes4HeaderWithFlags(tes4Flags));
        foreach (var formId in recordFormIds)
        {
            var recordData = BuildSubrecord("EDID", System.Text.Encoding.ASCII.GetBytes("TestRecord\0"));
            var record = BuildFlatRecordForTests(recordTag, recordData, formId);
            pluginBytes.AddRange(record);
        }

        return [.. pluginBytes];
    }

    private static byte[] BuildFlatRecordForTests(string tag, byte[] data, uint formId, uint flags = 0u)
    {
        var header = new byte[24];
        System.Text.Encoding.ASCII.GetBytes(tag.PadRight(4)[..4]).CopyTo(header, 0);
        BitConverter.TryWriteBytes(header.AsSpan(4), (uint)data.Length);
        BitConverter.TryWriteBytes(header.AsSpan(8), flags);
        BitConverter.TryWriteBytes(header.AsSpan(12), formId);
        return [.. header, .. data];
    }

    [Fact]
    public void RewriteArmaSubrecords_MatchingMod2_RewritesPath()
    {
        const string original = "meshes/armor/iron/iron_0.nif\0";
        const string expected = "meshes/slidesmith/cbbe/iron_0.nif";

        var origBytes = System.Text.Encoding.ASCII.GetBytes(original);
        byte[] data = BuildSubrecord("MOD2", origBytes);

        var rewriteMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["meshes/armor/iron/iron_0.nif"] = expected
        };

        var (newData, rewritten) = BinaryPluginRewriteService.RewriteArmaSubrecords(
            data, 0, data.Length, rewriteMap);

        Assert.Equal(1, rewritten);

        // Parse the output subrecord and verify the path.
        var subType = System.Text.Encoding.ASCII.GetString(newData, 0, 4);
        var subSize = (ushort)(newData[4] | (newData[5] << 8));
        var writtenPath = System.Text.Encoding.ASCII
            .GetString(newData, 6, subSize - 1); // exclude null terminator
        Assert.Equal("MOD2", subType);
        Assert.Equal(expected, writtenPath, StringComparer.OrdinalIgnoreCase);
    }

    [Fact]
    public void RewriteArmaSubrecords_Mod3Mod4Mod5_AllRewritten()
    {
        const string orig3 = "meshes/armor/iron/iron_m_0.nif\0";
        const string orig4 = "meshes/armor/iron/iron_1stf.nif\0";
        const string orig5 = "meshes/armor/iron/iron_1stm.nif\0";

        byte[] mod3 = BuildSubrecord("MOD3", System.Text.Encoding.ASCII.GetBytes(orig3));
        byte[] mod4 = BuildSubrecord("MOD4", System.Text.Encoding.ASCII.GetBytes(orig4));
        byte[] mod5 = BuildSubrecord("MOD5", System.Text.Encoding.ASCII.GetBytes(orig5));

        byte[] data = [..mod3, ..mod4, ..mod5];

        var rewriteMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["meshes/armor/iron/iron_m_0.nif"]  = "meshes/slidesmith/himbo/iron_m_0.nif",
            ["meshes/armor/iron/iron_1stf.nif"] = "meshes/slidesmith/himbo/iron_1stf.nif",
            ["meshes/armor/iron/iron_1stm.nif"] = "meshes/slidesmith/himbo/iron_1stm.nif",
        };

        var (_, rewritten) = BinaryPluginRewriteService.RewriteArmaSubrecords(
            data, 0, data.Length, rewriteMap);

        Assert.Equal(3, rewritten);
    }

    [Fact]
    public void RewriteArmaSubrecords_CaseInsensitiveLookup_MatchesUpperCasePath()
    {
        // Plugin stores path with Windows mixed-case backslashes; map key is lowercase.
        const string storedPath  = "Meshes\\Armor\\Iron\\Iron_0.nif\0";
        const string newPath     = "meshes/slidesmith/cbbe/iron_0.nif";
        const string mapKey      = "meshes/armor/iron/iron_0.nif";   // normalised lowercase

        byte[] data = BuildSubrecord("MOD2", System.Text.Encoding.ASCII.GetBytes(storedPath));

        var rewriteMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            [mapKey] = newPath
        };

        var (_, rewritten) = BinaryPluginRewriteService.RewriteArmaSubrecords(
            data, 0, data.Length, rewriteMap);

        // BinaryPluginRewriteService normalises path before lookup, so this should match.
        Assert.Equal(1, rewritten);
    }

    [Fact]
    public void RewriteArmaSubrecords_ExtendedSizeMod2_RewritesPath()
    {
        const string original = "meshes/armor/iron/iron_0.nif\0";
        const string expected = "meshes/slidesmith/cbbe/iron_0.nif";
        byte[] data = BuildExtendedSubrecord("MOD2", System.Text.Encoding.ASCII.GetBytes(original));

        var rewriteMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["meshes/armor/iron/iron_0.nif"] = expected
        };

        var (newData, rewritten) = BinaryPluginRewriteService.RewriteArmaSubrecords(
            data, 0, data.Length, rewriteMap);

        Assert.Equal(1, rewritten);
        Assert.Equal("MOD2", System.Text.Encoding.ASCII.GetString(newData, 0, 4));
        var subSize = (ushort)(newData[4] | (newData[5] << 8));
        var writtenPath = System.Text.Encoding.ASCII.GetString(newData, 6, subSize - 1);
        Assert.Equal(expected, writtenPath);
    }

    [Fact]
    public void RewriteArmaSubrecords_LongReplacementPath_WritesExtendedSizeSubrecord()
    {
        const string original = "meshes/armor/iron/iron_0.nif\0";
        var longPath = "meshes/slidesmith/" + new string('a', 70000) + ".nif";
        byte[] data = BuildSubrecord("MOD2", System.Text.Encoding.ASCII.GetBytes(original));

        var rewriteMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["meshes/armor/iron/iron_0.nif"] = longPath
        };

        var (newData, rewritten) = BinaryPluginRewriteService.RewriteArmaSubrecords(
            data, 0, data.Length, rewriteMap);

        Assert.Equal(1, rewritten);
        Assert.Equal("XXXX", System.Text.Encoding.ASCII.GetString(newData, 0, 4));
        Assert.Equal(4, (ushort)(newData[4] | (newData[5] << 8)));
        var extendedSize = newData[6] | (newData[7] << 8) | (newData[8] << 16) | (newData[9] << 24);
        Assert.Equal(longPath.Length + 1, extendedSize);
        Assert.Equal("MOD2", System.Text.Encoding.ASCII.GetString(newData, 10, 4));
        Assert.Equal(0, (ushort)(newData[14] | (newData[15] << 8)));
    }

