    [Fact]
    public async Task CreateMorphTransferContext_UsesExplicitTopologyConnectivityForIslandMembership()
    {
        var createContext = typeof(LocalExportService).GetMethod("CreateMorphTransferContext", BindingFlags.NonPublic | BindingFlags.Static);
        Assert.NotNull(createContext);

        var tmpDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tmpDir);

        try
        {
            var sourcePath = Path.Combine(tmpDir, "source-topology.nif");
            var targetPath = Path.Combine(tmpDir, "target-topology.nif");
            var vertices = new List<(float X, float Y, float Z)>();
            for (var column = 0; column < 6; column++)
            {
                vertices.Add((column * 0.010f, 0.000f, 0.000f));
                vertices.Add((column * 0.010f, 0.010f, 0.000f));
            }

            for (var column = 0; column < 6; column++)
            {
                vertices.Add((0.002f + (column * 0.010f), 0.002f, 0.000f));
                vertices.Add((0.002f + (column * 0.010f), 0.012f, 0.000f));
            }

            var triangles = new List<(ushort A, ushort B, ushort C)>();
            for (ushort column = 0; column < 5; column++)
            {
                var top = (ushort)(column * 2);
                var bottom = (ushort)(top + 1);
                var nextTop = (ushort)(top + 2);
                var nextBottom = (ushort)(top + 3);
                triangles.Add((top, bottom, nextTop));
                triangles.Add((bottom, nextBottom, nextTop));
            }

            for (ushort column = 0; column < 5; column++)
            {
                var baseIndex = (ushort)(12 + (column * 2));
                var top = baseIndex;
                var bottom = (ushort)(baseIndex + 1);
                var nextTop = (ushort)(baseIndex + 2);
                var nextBottom = (ushort)(baseIndex + 3);
                triangles.Add((top, bottom, nextTop));
                triangles.Add((bottom, nextBottom, nextTop));
            }

            await SyntheticNifTestData.WriteBsTriShapeStyleAsync(sourcePath, vertices, triangles);
            await SyntheticNifTestData.WriteBsTriShapeStyleAsync(targetPath, vertices, triangles);

            var context = createContext!.Invoke(null, new object[]
            {
                new[] { sourcePath },
                new[] { targetPath },
                new MeshAnalysis("mixed", false, 1),
                "CBBE"
            });

            Assert.NotNull(context);
            var targetTransferIslands = Assert.IsType<int[]>(context!.GetType().GetProperty("TargetTransferIslands", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(context));
            Assert.Equal(vertices.Count, targetTransferIslands.Length);
            Assert.Equal(2, targetTransferIslands.Distinct().Count());
            var decisionCache = context.GetType().GetProperty("DecisionCache", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(context);
            Assert.NotNull(decisionCache);
            var targetIslandTransfers = Assert.IsAssignableFrom<System.Collections.IDictionary>(
                decisionCache!.GetType().GetProperty("TargetIslandTransfers", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(decisionCache));
            Assert.Equal(2, targetIslandTransfers.Count);
        }
        finally
        {
            Directory.Delete(tmpDir, recursive: true);
        }
    }

    [Fact]
    public async Task CreateMorphTransferContext_BuildsSharedDecisionCacheForHardDivergence()
    {
        var createContext = typeof(LocalExportService).GetMethod("CreateMorphTransferContext", BindingFlags.NonPublic | BindingFlags.Static);
        Assert.NotNull(createContext);

        var tmpDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tmpDir);

        try
        {
            var sourcePath = Path.Combine(tmpDir, "source-divergent.nif");
            var targetPath = Path.Combine(tmpDir, "target-divergent.nif");
            await SyntheticNifTestData.WriteAsync(sourcePath,
            [
                (-0.8f, -0.2f, 0f), (-0.2f, -0.2f, 0f), (0.2f, 0.2f, 0f), (0.8f, 0.2f, 0f),
                (-0.7f, -0.2f, 0.35f), (-0.2f, -0.2f, 0.35f), (0.2f, 0.2f, 0.35f), (0.7f, 0.2f, 0.35f),
                (-0.35f, -0.15f, 1.0f), (-0.12f, -0.15f, 1.0f), (0.12f, 0.15f, 1.0f), (0.35f, 0.15f, 1.0f)
            ]);
            await SyntheticNifTestData.WriteAsync(targetPath,
            [
                (-0.8f, -0.2f, 0f), (-0.2f, -0.2f, 0f), (0.2f, 0.2f, 0f), (0.8f, 0.2f, 0f),
                (-0.7f, -0.2f, 0.35f), (-0.2f, -0.2f, 0.35f), (0.2f, 0.2f, 0.35f), (0.7f, 0.2f, 0.35f),
                (-2.6f, -0.55f, 1.0f), (-1.1f, -0.55f, 1.0f), (1.1f, 0.55f, 1.0f), (2.6f, 0.55f, 1.0f)
            ]);

            var context = createContext!.Invoke(null, new object[]
            {
                new[] { sourcePath },
                new[] { targetPath },
                new MeshAnalysis("plate", false, 1),
                "CBBE"
            });

            Assert.NotNull(context);
            var extremeRisk = Assert.IsType<bool>(context!.GetType().GetProperty("ExtremeTopologyAdaptationRisk", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(context));
            Assert.True(extremeRisk);

            var decisionCache = context.GetType().GetProperty("DecisionCache", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(context);
            Assert.NotNull(decisionCache);

            var targetDecisions = Assert.IsAssignableFrom<System.Collections.IEnumerable>(
                    decisionCache!.GetType().GetProperty("TargetDecisions", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(decisionCache))
                .Cast<object>()
                .ToArray();
            Assert.Equal(12, targetDecisions.Length);

            var divergenceScores = targetDecisions
                .Select(decision => (float)(decision.GetType().GetProperty("StructuralDivergence", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(decision) ?? 0f))
                .ToArray();
            Assert.Contains(divergenceScores, score => score >= 0.30f);
            var targetIslandTransfers = Assert.IsAssignableFrom<System.Collections.IDictionary>(
                decisionCache.GetType().GetProperty("TargetIslandTransfers", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(decisionCache));
            Assert.True(targetIslandTransfers.Count > 0);
            var islandDataLayer = decisionCache.GetType().GetProperty("IslandDataLayer", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(decisionCache);
            Assert.NotNull(islandDataLayer);
            var targetBoundaryBlendWeights = Assert.IsType<float[]>(
                islandDataLayer!.GetType().GetProperty("TargetBoundaryBlendWeights", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(islandDataLayer));
            Assert.Equal(12, targetBoundaryBlendWeights.Length);
            Assert.Contains(targetBoundaryBlendWeights, weight => weight > 0.05f);
        }
        finally
        {
            Directory.Delete(tmpDir, recursive: true);
        }
    }

