            influenceLists,
            new IReadOnlyList<int>[] { [1], [0, 2], [1] },
            new IReadOnlyList<int>[] { [1], [0, 2], [1] },
            null,
            null,
            new[] { Zone(0, 1, 0, 2), Zone(0, 1, 0, 2), Zone(0, 1, 0, 2) },
            new[] { Zone(0, 1, 0, 2), Zone(0, 1, 0, 2), Zone(0, 1, 0, 2) },
            new[] { 0, 0, 1 },
            new[] { 0, 0, 1 },
            new[] { 0, 1 },
            new[] { 0f, 0.80f, 0f },
            1f,
            1f,
            false,
            Array.Empty<string>(),
            null,
            null
        ]);

        var retargeted = new (float X, float Y, float Z)[]
        {
            (8f, 0f, 0f),
            (20f, 0f, 0f),
            (0f, 0f, 0f)
        };

        var result = Assert.IsAssignableFrom<IReadOnlyList<(float X, float Y, float Z)>>(
            stabilizeMethod!.Invoke(null, [retargeted, context]));

        Assert.True(result[1].X > 12f, $"Expected zone-aware stabilization to preserve the matching local side instead of averaging heavily across a cross-boundary neighbor, got {result[1].X}.");
        Assert.True(result[1].X < retargeted[1].X);
    }

    [Fact]
    public void StabilizeRetargetedMorphPayload_DampensCrossIslandFallbackNeighborsWhenSameIslandIsUnavailable()
    {
        var stabilizeMethod = typeof(LocalExportService).GetMethod("StabilizeRetargetedMorphPayload", BindingFlags.NonPublic | BindingFlags.Static);
        var contextType = typeof(LocalExportService).GetNestedType("MorphTransferContext", BindingFlags.NonPublic);
        var influenceType = typeof(LocalExportService).GetNestedType("MorphTransferInfluence", BindingFlags.NonPublic);
        Assert.NotNull(stabilizeMethod);
        Assert.NotNull(contextType);
        Assert.NotNull(influenceType);

        var influenceCtor = influenceType!.GetConstructors(BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)
            .Single(ctor => ctor.GetParameters().Length == 2);
        object CreateInfluence(int index, float weight) => influenceCtor.Invoke([index, weight]);

        var influenceListType = typeof(List<>).MakeGenericType(influenceType);
        object CreateInfluenceList(params object[] influences)
        {
            var list = (System.Collections.IList)Activator.CreateInstance(influenceListType)!;
            foreach (var influence in influences)
            {
                list.Add(influence);
            }

            return list;
        }

        var influenceArrayType = typeof(IReadOnlyList<>).MakeGenericType(influenceType);
        var influenceLists = Array.CreateInstance(influenceArrayType, 3);
        influenceLists.SetValue(CreateInfluenceList(CreateInfluence(0, 1f)), 0);
        influenceLists.SetValue(CreateInfluenceList(CreateInfluence(1, 0.30f), CreateInfluence(0, 0.70f)), 1);
        influenceLists.SetValue(CreateInfluenceList(CreateInfluence(2, 1f)), 2);

        static int Zone(int shell, int depth, int lateral, int height) => (((shell * 3) + depth) * 3 + lateral) * 5 + height;
        var contextCtor = contextType!.GetConstructors(BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)
            .Single(ctor => ctor.GetParameters().Length == 20);
        var context = contextCtor.Invoke(
        [
            new[] { new MeshVertex(0f, 0f, 0f), new MeshVertex(1f, 0f, 0f), new MeshVertex(2f, 0f, 0f) },
            new[] { new MeshVertex(0f, 0f, 0f), new MeshVertex(1f, 0f, 0f), new MeshVertex(2f, 0f, 0f) },
            new[] { 0, 1, 2 },
            influenceLists,
            new IReadOnlyList<int>[] { [1], [0, 2], [1] },
            new IReadOnlyList<int>[] { [1], [0, 2], [1] },
            null,
            null,
            new[] { Zone(0, 1, 0, 2), Zone(0, 1, 0, 2), Zone(0, 1, 0, 2) },
            new[] { Zone(0, 1, 0, 2), Zone(0, 1, 0, 2), Zone(0, 1, 0, 2) },
            new[] { 0, 0, 1 },
            new[] { 0, 0, 1 },
            new[] { 0, 1 },
            new[] { 0.78f, 0.80f, 0f },
            1f,
            1f,
            false,
            Array.Empty<string>(),
            null,
            null
        ]);

        var retargeted = new (float X, float Y, float Z)[]
        {
            (10f, 0f, 0f),
            (20f, 0f, 0f),
            (0f, 0f, 0f)
        };

        var result = Assert.IsAssignableFrom<IReadOnlyList<(float X, float Y, float Z)>>(
            stabilizeMethod!.Invoke(null, [retargeted, context]));

        Assert.True(result[1].X > 12.7f, $"Expected fallback stabilization to dampen cross-island neighbor influence instead of averaging equally across islands, got {result[1].X}.");
        Assert.True(result[1].X < retargeted[1].X);
    }

    [Fact]
    public void AdaptRetargetedMorphPayload_DampsRiskyPartHintsDuringExtremeTopologyReuse()
    {
        var adaptMethod = typeof(LocalExportService).GetMethod("AdaptRetargetedMorphPayload", BindingFlags.NonPublic | BindingFlags.Static);
        var contextType = typeof(LocalExportService).GetNestedType("MorphTransferContext", BindingFlags.NonPublic);
        var influenceType = typeof(LocalExportService).GetNestedType("MorphTransferInfluence", BindingFlags.NonPublic);
        Assert.NotNull(adaptMethod);
        Assert.NotNull(contextType);
        Assert.NotNull(influenceType);

        var influenceCtor = influenceType!.GetConstructors(BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)
            .Single(ctor => ctor.GetParameters().Length == 2);
        object CreateInfluence(int index, float weight) => influenceCtor.Invoke([index, weight]);

        var influenceListType = typeof(List<>).MakeGenericType(influenceType);
        object CreateInfluenceList(params object[] influences)
        {
            var list = (System.Collections.IList)Activator.CreateInstance(influenceListType)!;
            foreach (var influence in influences)
            {
                list.Add(influence);
            }

            return list;
        }

        var influenceArrayType = typeof(IReadOnlyList<>).MakeGenericType(influenceType);
        var influenceLists = Array.CreateInstance(influenceArrayType, 4);
        influenceLists.SetValue(CreateInfluenceList(CreateInfluence(0, 1f)), 0);
        influenceLists.SetValue(CreateInfluenceList(CreateInfluence(1, 1f)), 1);
        influenceLists.SetValue(CreateInfluenceList(CreateInfluence(2, 1f)), 2);
        influenceLists.SetValue(CreateInfluenceList(CreateInfluence(3, 1f)), 3);

        var contextCtor = contextType!.GetConstructors(BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)
            .Single(ctor => ctor.GetParameters().Length == 20);
        object CreateContext(IReadOnlyList<string> partHints) => contextCtor.Invoke(
        [
            new[]
            {
                new MeshVertex(-1f, 0f, 0f),
                new MeshVertex(1f, 0f, 0f),
                new MeshVertex(-1f, 0f, 1f),
                new MeshVertex(1f, 0f, 1f)
            },
            new[]
            {
                new MeshVertex(-0.5f, 0f, 0f),
                new MeshVertex(0.5f, 0f, 0f),
                new MeshVertex(-4f, 0f, 1f),
                new MeshVertex(4f, 0f, 1f)
            },
            new[] { 0, 1, 2, 3 },
            influenceLists,
            new IReadOnlyList<int>[] { [1, 2], [0, 3], [0, 3], [1, 2] },
            new IReadOnlyList<int>[] { [1, 2], [0, 3], [0, 3], [1, 2] },
            null,
            null,
            new[] { 15, 20, 17, 22 },
            new[] { 15, 20, 17, 22 },
            new[] { 0, 0, 1, 1 },
            new[] { 0, 0, 1, 1 },
            new[] { 0, 1 },
            new[] { 0.22f, 0.26f, 0.18f, 0.14f },
            1f,
            1f,
            true,
            partHints,
            null,
            null
        ]);

        var retargeted = new (float X, float Y, float Z)[]
        {
            (1f, 0f, 0.25f),
            (1f, 0f, 0.25f),
            (1f, 0f, 0.25f),
            (1f, 0f, 0.25f)
        };

        var baseline = Assert.IsAssignableFrom<IReadOnlyList<(float X, float Y, float Z)>>(
            adaptMethod!.Invoke(null, [retargeted, CreateContext(Array.Empty<string>())]));
        var hinted = Assert.IsAssignableFrom<IReadOnlyList<(float X, float Y, float Z)>>(
            adaptMethod.Invoke(null, [retargeted, CreateContext(new[] { "split-mesh", "strap-like", "lower-drape", "open-window" })]));

        Assert.Equal(4, baseline.Count);
        Assert.Equal(4, hinted.Count);
        Assert.True(Math.Abs(hinted[0].X - 1f) < Math.Abs(baseline[0].X - 1f), "Expected risky lower-body part hints to keep reused lateral deltas closer to neutral for extreme topology reuse.");
        Assert.True(Math.Abs(hinted[1].X - 1f) < Math.Abs(baseline[1].X - 1f), "Expected risky split/strap hints to damp lower-body topology adaptation.");
        Assert.True(Math.Abs(hinted[0].Z - 0.25f) < Math.Abs(baseline[0].Z - 0.25f), "Expected risky part hints to reduce axial over-adaptation in lower drape/open regions.");
        Assert.True(Math.Abs(hinted[1].Z - 0.25f) < Math.Abs(baseline[1].Z - 0.25f), "Expected risky split/strap hints to reduce axial over-adaptation.");
    }

    private static void AssertDeltasEqual(
        IReadOnlyList<(float X, float Y, float Z)> expected,
        IReadOnlyList<(float X, float Y, float Z)> actual)
    {
        Assert.Equal(expected.Count, actual.Count);
        for (var index = 0; index < expected.Count; index++)
        {
            Assert.Equal(expected[index].X, actual[index].X, 3);
            Assert.Equal(expected[index].Y, actual[index].Y, 3);
            Assert.Equal(expected[index].Z, actual[index].Z, 3);
        }
    }

    [Fact]
    public async Task ExportAsync_DependencyMap_IncludesDetectedBodyAndFormIds()
    {
        var tmpDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tmpDir);
        var nifPath = Path.Combine(tmpDir, "iron_0.nif");
        await File.WriteAllBytesAsync(nifPath, new byte[128]);

        try
        {
            var service = new LocalExportService(groundMeshGen: null);
            var outputDir = Path.Combine(tmpDir, "output");
            Directory.CreateDirectory(outputDir);

            var request    = new ConversionRequest(nifPath, "CBBE", OutputDirectory: outputDir);
            var armor      = new ImportedArmor(nifPath, [nifPath], [], [], []);
            var analysis   = new MeshAnalysis("plate", false, 1);
            var mesh       = new ConvertedMesh("plate", "direct-copy", 1, new Dictionary<string, double>());
            var morphs     = new MorphSet("low", "high", true);
            var physics    = new PhysicsConfig("none");
            var clipping   = new ClippingReport(false, [], []);
            var correction = new CorrectionResult(false, "not-required");
            var bsProject  = new BodySlideProject("TestProject", "CBBE", ["Belly"], "<BodySlideProject/>");
            // Provide an ARMA addon with a real FormId so the enriched map records it.
            var addon      = new PluginArmorAddon("ARMA", [$"meshes/{Path.GetFileName(nifPath)}"], FormId: 0x00001234, EditorId: "IronCuirass");
            var pluginResult = new PluginAnalysisResult(["TestMod.esp"], [addon], "patch-guidance");
            var textures   = new TextureSummary(0, [], [], []);
            var pose       = new PoseSimulationResult([], new Dictionary<string, IReadOnlyList<string>>(), [], 0);
            var detected   = new BodyDetectionReport("UUNP", 0.91, ["reference:91%"]);
            var skel       = new SkeletonMappingResult("XPMSSE", "CBBE", [], []);
            var voxel      = new VoxelCollisionResult(false, [], new Dictionary<string, double>(), 16);

            var (_, files) = await service.ExportAsync(
                request, armor, analysis, mesh, morphs, physics,
                clipping, correction, bsProject, pluginResult,
                textures, pose, ["step1"],
                detected, skel, null, voxel,
                CancellationToken.None);

            var depMapPath = files.FirstOrDefault(f => f.EndsWith("dependency-map.json", StringComparison.OrdinalIgnoreCase));
            Assert.NotNull(depMapPath);
            Assert.True(File.Exists(depMapPath));

            var json = await File.ReadAllTextAsync(depMapPath!);
            Assert.Contains("UUNP", json);               // detected source body
            Assert.Contains("XPMSSE", json);             // source skeleton
            Assert.Contains("0x00001234", json);         // ARMA FormID
        }
        finally
        {
            Directory.Delete(tmpDir, recursive: true);
        }
    }
}

