    [Fact]
    public void ApplyIncrementalIslandAwareCageTuning_UsesPiecewiseFallbackForRiskyIslandUpdates()
    {
        var method = typeof(StrategyMeshConversionService).GetMethod("ApplyIncrementalIslandAwareCageTuning", BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public);
        Assert.NotNull(method);

        var previous = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase)
        {
            ["chest"] = 1.08d,
            ["waist"] = 0.92d,
            ["arms"] = 1.04d
        };
        var updated = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase)
        {
            ["chest"] = 1.34d,
            ["waist"] = 0.72d,
            ["arms"] = 1.20d
        };
        var baseCage = BasicCageGenerationService.CreatePresetCage("mixed");
        var semanticOnlyCage = baseCage with
        {
            IslandControls =
            [
                new CageIslandControl(
                    "armor",
                    0,
                    ["chest", "waist"],
                    SemanticLabels: ["window-frame-island"],
                    WidthScaleBias: 0.80f,
                    DepthScaleBias: 0.84f,
                    HeightScaleBias: 0.88f)
            ]
        };
        var piecewiseCage = semanticOnlyCage with
        {
            IslandControls =
            [
                semanticOnlyCage.IslandControls![0] with
                {
                    BoundaryLoops =
                    [
                        new CageIslandBoundaryLoopControl(0, ["chest", "waist"], IsHole: true)
                    ],
                    EdgeNetworkSummary = new TopologyIslandEdgeNetworkSummary(
                        0,
                        BoundaryEdgeCount: 10,
                        InteriorEdgeCount: 8,
                        NonManifoldEdgeCount: 1,
                        BoundaryVertexCount: 12,
                        MaxVertexValence: 5,
                        IsClosedManifold: false,
                        HasManifoldRisk: true)
                }
            ]
        };

        var semanticOnly = Assert.IsAssignableFrom<IReadOnlyDictionary<string, double>>(method!.Invoke(null, [previous, updated, semanticOnlyCage]));
        var piecewise = Assert.IsAssignableFrom<IReadOnlyDictionary<string, double>>(method.Invoke(null, [previous, updated, piecewiseCage]));

        Assert.True(piecewise["chest"] < semanticOnly["chest"]);
        Assert.True(Math.Abs(piecewise["waist"] - previous["waist"]) < Math.Abs(semanticOnly["waist"] - previous["waist"]));
        Assert.Equal(semanticOnly["arms"], piecewise["arms"], 6);
    }

    [Fact]
    public void ApplyIncrementalIslandAwareCageTuning_DampsUniquelyOwnedRegionsAcrossMultipleIslands()
    {
        var method = typeof(StrategyMeshConversionService).GetMethod("ApplyIncrementalIslandAwareCageTuning", BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public);
        Assert.NotNull(method);

        var previous = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase)
        {
            ["chest"] = 1.10d,
            ["arms"] = 1.10d
        };
        var updated = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase)
        {
            ["chest"] = 1.30d,
            ["arms"] = 1.30d
        };

        var result = Assert.IsAssignableFrom<IReadOnlyDictionary<string, double>>(method!.Invoke(null, [previous, updated, CreateMultiIslandOwnershipCage()]));

        Assert.True(result["chest"] < result["arms"]);
        Assert.True(result["chest"] < 1.24d);
    }

    // Mesh conversion service that forces high regional morphing to trigger clipping.
    private sealed class ForcedClippingMeshConversionService : IMeshConversionService
    {
        public Task<ConvertedMesh> ConvertAsync(
            ImportedArmor armor, MeshAnalysis analysis, DeformationCage cage,
            string targetBody, string? deformationProfile, string? sourceBody, CancellationToken ct) =>
            Task.FromResult(new ConvertedMesh(
                analysis.MeshType,
                "forced-clipping",
                analysis.MeshCount,
                new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase)
                {
                    ["chest"]     = 1.30,  // above all clipping thresholds
                    ["breasts"]   = 1.28,
                    ["shoulders"] = 1.25,
                    ["armpits"]   = 1.22,
                    ["waist"]     = 1.20,
                    ["butt"]      = 1.25,
                    ["pelvis"]    = 1.22,
                    ["thighs"]    = 1.18,
                },
                cage));
    }

    private static DeformationCage CreateForcedIslandAwareCage() =>
        new(
            "hybrid-cage",
            new Dictionary<string, CageRegion>(StringComparer.OrdinalIgnoreCase)
            {
                ["chest"] = new(0.78f, 0.24f)
            },
            [
                new CageIslandControl(
                    MeshKey: "forced-island-aware",
                    IslandId: 0,
                    CageRegions: ["chest"],
                    WidthScaleBias: 0.80f,
                    DepthScaleBias: 0.80f,
                    HeightScaleBias: 0.80f)
            ]);

    private static DeformationCage CreateMultiIslandOwnershipCage() =>
        new(
            "hybrid-cage",
            new Dictionary<string, CageRegion>(StringComparer.OrdinalIgnoreCase)
            {
                ["chest"] = new(0.78f, 0.24f),
                ["arms"] = new(0.92f, 0.10f, 0.92f, 0.18f, 0.50f, 0.58f)
            },
            [
                new CageIslandControl(
                    MeshKey: "ownership-mesh",
                    IslandId: 0,
                    CageRegions: ["chest"],
                    SemanticLabels: ["window-frame-island"],
                    BoundaryLoops:
                    [
                        new CageIslandBoundaryLoopControl(0, ["chest"], IsHole: true)
                    ],
                    AuthoredRegions:
                    [
                        new CageIslandAuthoredRegion("chest", new CageRegion(0.78f, 0.18f), LoopIndex: 0, IsHole: true)
                    ]),
                new CageIslandControl(
                    MeshKey: "ownership-mesh",
                    IslandId: 1,
                    CageRegions: ["arms"],
                    WidthScaleBias: 0.94f,
                    DepthScaleBias: 0.94f,
                    HeightScaleBias: 0.94f)
            ]);

    // Voxel service that always reports penetrations in the chest region.
    private sealed class AlwaysPenetratingVoxelCollisionService : IVoxelCollisionService
    {
        public Task<VoxelCollisionResult> ComputeAsync(
            ImportedArmor armor, ConvertedMesh mesh, string targetBody, CancellationToken ct) =>
            Task.FromResult(new VoxelCollisionResult(
                true,
                ["chest", "waist"],
                new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase)
                {
                    ["chest"] = 3.0,
                    ["waist"] = 1.5,
                },
                8));
    }


    private sealed class CaptureConvertedMeshExporter : IExportService
    {
        public ConvertedMesh? CapturedMesh { get; private set; }

        public Task<(string OutputDirectory, IReadOnlyList<string> OutputFiles)> ExportAsync(
            ConversionRequest request,
            ImportedArmor armor,
            MeshAnalysis analysis,
            ConvertedMesh mesh,
            MorphSet morphs,
            PhysicsConfig physics,
            ClippingReport clipping,
            CorrectionResult correction,
            BodySlideProject bodySlideProject,
            PluginAnalysisResult pluginAnalysis,
            TextureSummary textureSummary,
            PoseSimulationResult poseSimulation,
            IReadOnlyList<string> steps,
            BodyDetectionReport detectedBody,
            SkeletonMappingResult skeletonMapping,
            RaceCompatibilityReport? raceCompatibility,
            VoxelCollisionResult voxelResult,
            CancellationToken cancellationToken)
        {
            CapturedMesh = mesh;
            return Task.FromResult<(string, IReadOnlyList<string>)>((request.OutputDirectory ?? Path.GetTempPath(), []));
        }
    }
}

